// 단순하게 pq 하나로 중간값 못찾음
// 내부는 정렬되어있지 않고 계속 복사해서 찾으면 time limit
// 최대힙 최소힙으로 2개 만들어서 관리

#include <iostream>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    priority_queue<int> prior;                           // 중간값보다 작은 값들 저장 내림차순
    priority_queue<int, vector<int>, greater<int>> back; // 중간값보다 큰 값들 저장 오름차순

    while (N--) {
        int n;
        cin >> n;

        // 앞에거 비었거나  push
        if (prior.empty() || n < prior.top())
            prior.push(n);
        else
            back.push(n);

        // 앞에가 개수가 더 많으면 뒤로 보내서 조정
        if (prior.size() > back.size() + 1) {
            back.push(prior.top());
            prior.pop();
        }
        else if (prior.size() < back.size()) {
            prior.push(back.top());
            back.pop();
        }

        cout << prior.top() << "\n";
    }
}

// depth 맞추고 한 단계씩 끌어올리면서 맞추기
// LCA 문제 O(N)에서 이분탐색으로 O(logN) 가능

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T;
    cin >> T;

    while (T--) {
        int N;
        vector<int> parent;
        int node1, node2;
        int dep1 = 0, dep2 = 0;

        cin >> N;
        parent.resize(N + 1, -1);
        N--;
        while (N--) {
            int A, B;
            cin >> A >> B;
            parent[B] = A;
        }
        cin >> node1 >> node2;

        for (int next = node1; next != -1; next = parent[next])
            dep1++;
        for (int next = node2; next != -1; next = parent[next])
            dep2++;

        // depth 맞추기
        int dif = abs(dep1 - dep2);
        if (dep1 > dep2) {
            while (dif--) {
                node1 = parent[node1];
            }
        }
        else {
            while (dif--) {
                node2 = parent[node2];
            }
        }

        while (node1 != node2) {
            node1 = parent[node1];
            node2 = parent[node2];
        }

        cout << node1 << "\n";
    }
}

// cctv 종류 5가지, -> 부터 (0 1 2 3)
// 1: 한쪽  |  2: 반대 2개  |  3: 인접 2개  |  4: 3방향  |  5: 모든 방향
// 0: 빈칸, 6: 벽
// 벽은 통과 못하고 cctv는 통과 가능
// 방향을 적절하게 설정해 사각지대 최소화시키기
// 방향 전부 따지면서 경우의수 따지기 cctv 최대 8개 -> 4^8 Max
// 재귀?
// -----------------------------------------------------------------------
// black에서 매번 visited를 복사하면 시간이 매우 증가되므로 감시 영역을 저장했다가 복원하는 방법으로 최적화 필요
// 전역이나 main에서 미리 만들어서 백트래킹 함수로 넘겨주는게 좋음

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct info {
    int y, x, type; // 좌표, 종류
    vector<int> dir;
};
int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};

// CCTV 하나씩 감시 구역 계산하기
void go(int N, int M, const vector<vector<int>>& grid, const info& cctv, vector<vector<int>>& visited) {
    for (int d : cctv.dir) {
        int ny = cctv.y;
        int nx = cctv.x;

        while (1) {
            ny += diry[d];
            nx += dirx[d];
            if (ny < 0 || nx < 0 || ny >= N || nx >= M) break;  // grid 벗어나면 중지
            if (grid[ny][nx] == 6) break;                       // 벽이면 탐색 중지
            if (grid[ny][nx] > 0 && grid[ny][nx] < 6) continue; // CCTV면 통과

            visited[ny][nx] = 7; // 감시되는 지역 표시
        }
    }
}

// 사각지대 크기 구하는 함수
void black(const vector<vector<int>>& grid, const vector<info>& CCTV, const vector<vector<vector<int>>> DIR, int& ans) {
    int N = grid.size();
    int M = grid[0].size();
    int cnt = 0;                        // ans와 비교, 감시 지역 하나마다 1씩 줄여나감
    vector<vector<int>> visited = grid; // 방문 여부

    for (info cctv : CCTV) {
        go(N, M, grid, cctv, visited);
    }

    for (int y = 0; y < N; y++) {
        for (int x = 0; x < M; x++) {
            if (visited[y][x] == 0) cnt++;
        }
    }

    ans = min(ans, cnt);
}

// MIN 찾는 재귀함수
void func(int depth, const vector<vector<int>>& grid, vector<info>& CCTV, const vector<vector<vector<int>>> DIR, int& ans) {
    if (depth >= CCTV.size()) {
        black(grid, CCTV, DIR, ans);
        return;
    }

    // CCTV의 종류에 따라 저장된 감시 방향마다 수행
    for (vector<int> d : DIR[depth]) {
        CCTV[depth].dir = d;
        func(depth + 1, grid, CCTV, DIR, ans);
    }
}

int main() {
    int N, M;                        // N x M 크기 (최대 8 x 8)
    vector<vector<int>> grid;        // 사무실
    vector<info> CCTV;               // cctv 위치
    vector<vector<vector<int>>> DIR; // cctv 방향 설정, 3차원으로 저장
    int ans = 21e8;                  // 답

    cin >> N >> M;
    grid.assign(N, vector<int>(M));
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < M; c++) {
            cin >> grid[r][c];
            if (grid[r][c] > 0 && grid[r][c] < 6) CCTV.push_back({r, c, grid[r][c]}); // cctv 위치 저장
            // cctv 종류에 따라 방향 저장
            switch (grid[r][c]) {
            case 1:
                DIR.push_back({{0}, {1}, {2}, {3}});
                break;
            case 2:
                DIR.push_back({{0, 2}, {1, 3}});
                break;
            case 3:
                DIR.push_back({{0, 1}, {1, 2}, {2, 3}, {3, 0}});
                break;
            case 4:
                DIR.push_back({{0, 1, 2}, {1, 2, 3}, {2, 3, 0}, {3, 0, 1}});
                break;
            case 5:
                DIR.push_back({{0, 1, 2, 3}});
                break;
            }
        }
    }

    func(0, grid, CCTV, DIR, ans);
    cout << ans << "\n";
}

// 최단 경로에 포함되지 않은 도로중 --> 가장 최단 경로
// 단방향 도로
// 0-based
// 최단경로들은 중복이 가능
// 먼저 다익스트라 해서 기존 최단거리의 경로를 모두 저장
// 중복 경로 포함하려면 다익스트라 할 때 roads에서 >= 대신 >로 해서 같은 경우도 포함
// 경로 저장해서 정점에서 경로에 해당하는 다음 정점에 대해 false 설정
// 기존에 path를 갱신시키면서 했는데 2개 이상 들어갈 때 경우 고려
// --> dist랑 거리가 같으면 그대로 push, 작으면 clear하고 push
// paths 만들었으면 다시 다익스트라 하면서 paths 지나갈 경우들은 제외
// --------------------------------------------------------------------------------
// parent 만들 때 dist보다 같으면 push만 하고 pass, 작으면 기존 parent 없애고 push
// 경로 저장할 때 parent 순회하면서 2차원 visited 사용, paths는 set 사용해야 안터짐

#include <iostream>
#include <vector>
#include <queue>
#include <string.h>
#include <unordered_set>
using namespace std;
const int INF = 21e8;

struct node {
    int to, len; // 위치, 길이
    bool operator<(node other) const {
        return len > other.len;
    }
};

void origin_dijkstra(int start, int end, const vector<vector<node>>& roads, vector<unordered_set<int>>& paths) {
    int size = roads.size();
    vector<int> dist(size, INF);
    vector<vector<int>> parents(size); // parent

    dist[start] = 0;
    priority_queue<node> pq;
    pq.push({start, 0});

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.len > dist[now.to]) continue;

        for (int i = 0; i < roads[now.to].size(); i++) {
            node next = roads[now.to][i];
            int next_len = now.len + next.len;
            if (next_len > dist[next.to]) {
                continue;
            }
            else if (next_len < dist[next.to]) {
                parents[next.to].clear(); // 기존 길이보다 작으면 모든 parent 삭제, 같으면 유지
            }
            parents[next.to].push_back(now.to); // parent에 중복으로 저장
            if (next_len == dist[next.to]) {
                continue;
            }

            dist[next.to] = next_len;
            pq.push({next.to, next_len});
        }
    }

    // end 부터 역추적하며 paths에 최단경로 저장 --> queue 이용
    int visited[501][501];
    memset(visited, 0, sizeof(visited));
    queue<int> q;
    q.push(end);

    while (!q.empty()) {
        int now = q.front();
        q.pop();

        for (int i = 0; i < parents[now].size(); i++) {
            int next = parents[now][i];
            if (visited[next][now] == 1) continue;
            visited[next][now] = 1;
            paths[now].insert(next);
            q.push(next);
        }
    }
}

int next_dijkstra(int start, int end, const vector<vector<node>>& roads, const vector<unordered_set<int>>& paths) {
    int size = roads.size();
    vector<int> dist(size, INF);

    dist[start] = 0;
    priority_queue<node> pq;
    pq.push({start, 0});

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.len > dist[now.to]) continue;

        for (int i = 0; i < roads[now.to].size(); i++) {
            node next = roads[now.to][i];
            bool flag = true; // 기존 최단경로에 대한 flag
            if (paths[next.to].find(now.to) != paths[next.to].end()) flag = false;
            if (!flag) continue; // 기존 최단경로 포함이면 pass

            int next_len = now.len + next.len;
            if (next_len >= dist[next.to]) continue;

            dist[next.to] = next_len;
            pq.push({next.to, next_len});
        }
    }

    return dist[end];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    while (1) {
        int N, M;                         // 장소 수, 도로 수
        int S, D;                         // 시작점, 도착점
        vector<vector<node>> roads;       // 도로
        vector<unordered_set<int>> paths; // 경로 저장
        cin >> N >> M;
        if (N == 0 && M == 0) break; // 마지막 입력 0 0 이면 종료
        cin >> S >> D;
        roads.resize(N);
        paths.resize(N);
        for (int i = 0; i < M; i++) {
            int U, V, P; // U에서 V로 가는 길이 P의 도로
            cin >> U >> V >> P;
            roads[U].push_back({V, P});
        }
        origin_dijkstra(S, D, roads, paths);
        int ans = next_dijkstra(S, D, roads, paths);

        if (ans == INF) ans = -1;
        cout << ans << "\n";
    }
}

