#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    vector<int> stairs;
    vector<vector<int>> dp;

    cin >> N;
    stairs.resize(N);
    dp.resize(N, vector<int>(2, 0));
    for (int i = 0; i < N; i++) {
        cin >> stairs[i];
    }

    dp[0][0] = stairs[0];
    if (N >= 2) {
        dp[1][0] = stairs[1];
        dp[1][1] = dp[0][0] + stairs[1];

        for (int i = 2; i < N; i++) {
            dp[i][0] = max(dp[i - 2][0], dp[i - 2][1]) + stairs[i];
            dp[i][1] = dp[i - 1][0] + stairs[i];
        }
    }


    cout << max(dp[N - 1][0], dp[N - 1][1]) << "\n";
}

#include <iostream>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;


int n;
vector<double> building;
int ans;

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        int temp;
        cin >> temp;
        building.push_back(temp);
    }

    if (building.size() == 1) {
        std ::cout << "0\n";
        return 0;
    }

    for (int i = 0; i < n; i++) {
        int cnt = 0; // i번째마다 몇 개 보이는지 카운트
        for (int j = 0; j < n; j++) {
            double slope = 0;
            double y = 0;

            if (i == j) continue;
            if (abs(i - j) == 1) {
                cnt++;
                continue;
            }
            if (building[i] == building[j])
                y = building[i];
            else {
                slope = ((building[i] - building[j]) / (i - j)); // i, j 사이 기울기
                y = building[j] - slope * j;                     // y절편
            }
            cnt++; // 다른 빌딩마다 미리 +1하고 선분에 걸리면 -1

            // 선분 그었을 때 사이에 있는 좌표의 빌딩의 높이가 더 높은지 아닌지
            if (i < j) {
                for (int tar = i + 1; tar < j; tar++) {
                    if (building[tar] >= slope * tar + y) {
                        cnt--;
                        break;
                    }
                }
            }
            else if (i > j) {
                for (int tar = i - 1; tar > j; tar--) {
                    if (building[tar] >= slope * tar + y) {
                        cnt--;
                        break;
                    }
                }
            }
        }
        if (cnt > ans) ans = cnt;
    }
    cout << ans;
}

// 공유기를 집에 설치
// 가장 가까운 두 공유기의 거리를 최대로
// =============================================================================
// 파라메트릭 서치로
// 그리디하게 제일 왼쪽부터 시작해서 일정 거리 이상마다 두면서 끝까지 가능한지

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, C;          // 집, 공유기
    vector<int> house; // 집 좌표

    cin >> N >> C;
    house.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> house[i];
    }
    sort(house.begin(), house.end());

    int left = 0, right = house[N - 1] - house[0];
    int mid;

    while (left <= right) {
        mid = (left + right) / 2;
        int cnt = 1, pre = 0, next = 1;

        // 그리디하게 설치해보기
        while (next < N) {
            if (house[next] - house[pre] >= mid) {
                cnt++;
                pre = next;
            }
            next++;
        }

        if (cnt < C) {
            right = mid - 1;
        }
        else {
            left = mid + 1;
        }
    }

    cout << right << "\n";
}

// 순서대로 도착
// heap으로 빼기
// =================================================================
// union-find 문제
// 이 문제에서 Union 함수는 필요 없음
// parent[MAX] = find(MAX - 1) 로 갱신

#include <iostream>
#include <vector>
using namespace std;

int G, P; // 게이트, 비행기
vector<int> parent;
int ans = 0;

int find(int now) {
    if (now == parent[now]) return now;
    return parent[now] = find(parent[now]);
}

void Union(int a, int b) {
    int roota = find(a);
    int rootb = find(b);
    if (roota == rootb) return;
    parent[rootb] = roota;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> G >> P;
    parent.resize(G + 1, 0);
    for (int i = 1; i <= G; i++) {
        parent[i] = i;
    }

    for (int i = 0; i < P; i++) {
        int g;
        cin >> g;

        int MAX = find(g);
        if (!MAX) break;

        Union(MAX - 1, MAX);
        ans++;
    }

    cout << ans << "\n";
}

// 하나하나 잘라가며 최대 길이로 조카 수마다 나눠주기
// 파라메트릭 서치
// ==================================================================================================
// 파라메트릭 서치 할 때 left = 1 시작, 출력은 right로
// 처음에 vector size 설정하는게 더 메모리 적게 먹음
// sort보다 max_element 써서 max값만 뽑으면 더 빠름

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int M, N; // 조카 수, 과자 수
    vector<int> snack;

    cin >> M >> N;
    snack.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> snack[i];
    }

    // sort(snack.begin(), snack.end(), greater<>());
    int left = 1, right = *max_element(snack.begin(), snack.end());
    int mid = 0;
    bool flag = false;

    while (left <= right) {
        mid = (left + right) / 2;
        int cnt = 0;

        for (const int& len : snack) {
            cnt += len / mid;
        }

        // cout << "left = " << left << ", right = " << right << " --> mid = " << mid << ", cnt = " << cnt << "\n";
        if (cnt >= M) {
            flag = true;
            left = mid + 1;
        }
        else {
            right = mid - 1;
        }
    }

    if (flag)
        cout << right << "\n";
    else
        cout << 0 << "\n";
}

