// 값을 찾는 이분탐색일 때는 left를 1로 두기

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, K; // 만들 랜선 수, 가지고 있는 랜선 수
    vector<ll> cable;
    cin >> K >> N;
    for (int i = 0; i < K; i++) {
        ll len;
        cin >> len;
        cable.push_back(len);
    }

    sort(cable.begin(), cable.end());
    ll left = 1, right = cable[K - 1];
    ll mid;

    while (left <= right) {
        mid = (left + right) / 2;
        ll cnt = 0;

        for (const auto& len : cable) {
            cnt += (len / mid);
        }
        // 많이 만들 수 있으면 길이를 더 늘림
        if (cnt >= N) {
            left = mid + 1;
        }
        else {
            right = mid - 1;
        }
    }

    cout << right << "\n";
}

// W x H grid
// c를 연결하기 위해 필요한 거울 개수의 min
// 거울 /  \  에 닿으면 굴절
// 빈칸 .  벽 *   출발도착 c
// bfs하면서 회전한 횟수, 맨해튼 거리 기준으로 도착점까지 진행
// 우선순위큐 cnt가 적을수록 -> dist가 작을수록
// deque로 01 bfs 해보기 --> 안됨
// ------------------------------------------------------------------------------------
// 같은 지점에 더 적은 거울로 올 수 있음
// 단순하게 visited 0 1 X
// dir 추가해 3차원으로 만들어서 dp

#include <iostream>
#include <vector>
#include <queue>
#include <deque>
#include <string>
#include <cmath>
using namespace std;
using PR = pair<int, int>;
const int INF = 21e8;

struct node {
    int y, x, dir, cnt, dist;
    bool operator<(node other) const {
        if (cnt != other.cnt) return cnt > other.cnt;
        return dist > other.dist;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int W, H;
    vector<string> grid;
    vector<PR> C; // 출발 도착
    cin >> W >> H;

    for (int i = 0; i < H; i++) {
        string line;
        cin >> line;
        grid.push_back(line);
    }
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (grid[y][x] == 'C') C.push_back({y, x});
        }
    }

    vector<PR> dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}; // 상 하 좌 우 0 1 2 3
    vector<vector<vector<int>>> visited(H, vector<vector<int>>(W, vector<int>(4, INF)));
    // deque<node> q;
    priority_queue<node> pq;
    pq.push({C[0].first, C[0].second, -1, 0, abs(C[0].first - C[1].first) + abs(C[0].second - C[1].second)}); // 처음 시작 dir -1로 설정

    while (1) {
        node now = pq.top();
        pq.pop();
        // 다른 C에 도착하면 cnt 출력하고 종료
        if (now.y == C[1].first && now.x == C[1].second) {
            cout << now.cnt << "\n";
            break;
        }

        for (int i = 0; i < 4; i++) {
            int ny = now.y + dirs[i].first;
            int nx = now.x + dirs[i].second;

            if (ny < 0 || nx < 0 || ny >= H || nx >= W) continue; // grid 벗어나면 pass
            if (grid[ny][nx] == '*') continue;                    // 벽이면 pass

            // 제일 처음
            if (now.dir == -1) {
                visited[ny][nx][i] = now.cnt;
                pq.push({ny, nx, i, now.cnt, abs(now.y - ny) + abs(now.x - nx)});
                continue;
            }
            // 방향 같으면 cnt 증가 x
            if (now.dir == i) {
                if (now.cnt >= visited[ny][nx][i]) continue;
                visited[ny][nx][i] = now.cnt;
                pq.push({ny, nx, i, now.cnt, abs(now.y - ny) + abs(now.x - nx)});
            }
            // 방향 달라지면 cnt++
            else {
                if (now.cnt + 1 >= visited[ny][nx][i]) continue;
                visited[ny][nx][i] = now.cnt + 1;
                pq.push({ny, nx, i, now.cnt + 1, abs(now.y - ny) + abs(now.x - nx)});
            }
        }
    }
}

// 왼쪽, 오른쪽, 아래쪽으로만 이동
// 한번 간 곳은 안감
// (1,1) --> (N, M) 최대 구하기
// visited 좌표마다 만들면 안됨
// 아래로만 가기 때문에 한 줄마다 dp 계산하면 가능

#include <iostream>
#include <vector>
#include <string.h>
#include <algorithm>
using namespace std;

int N, M;
vector<vector<int>> grid;   // N x M 지형
int dp[1001][1001];         // 가치 최대값 DP
int dx[] = {-1, 1};         // 왼쪽, 오른쪽
int LtoR[1001], RtoL[1001]; // 행마다 왼쪽 오른쪽 경로 계산

int main() {
    cin >> N >> M;
    grid.resize(N + 1, vector<int>(M + 1));
    for (int y = 1; y <= N; y++) {
        for (int x = 1; x <= M; x++) {
            cin >> grid[y][x];
        }
    }

    dp[1][1] = grid[1][1];
    for (int x = 2; x <= M; x++) {
        dp[1][x] += dp[1][x - 1] + grid[1][x];
    }

    for (int y = 2; y <= N; y++) {
        // 위에서, 왼쪽에서
        LtoR[1] = dp[y - 1][1] + grid[y][1];
        for (int x = 2; x <= M; x++) {
            LtoR[x] = max(dp[y - 1][x], LtoR[x - 1]) + grid[y][x];
        }
        // 위에서, 오른쪽에서
        RtoL[M] = dp[y - 1][M] + grid[y][M];
        for (int x = M - 1; x >= 1; x--) {
            RtoL[x] = max(dp[y - 1][x], RtoL[x + 1]) + grid[y][x];
        }
        // LtoR, RtoL 중 큰 값으로 갱신
        for (int x = 1; x <= M; x++) {
            dp[y][x] = max(LtoR[x], RtoL[x]);
        }
    }

    cout << dp[N][M];
}

