int MAX = -1;                  // 상어가 제거할 물고기 최대 수
vector<int> dir_shark(3, -1);  // 상어가 움직이는 방향
vector<int> dir_record(3, -1); // 방향 기록
int ans = 0;

void dfs(int y, int x, int depth, int cnt) {
