            }
        }

        visited[ny][nx]++;
        dfs(ny, nx, depth + 1, cnt + sum);
        visited[ny][nx]--;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> M >> S;
    for (int i = 0; i < M; i++) {
        int x, y, d;
        cin >> x >> y >> d;
        grid[x - 1][y - 1][d - 1]++;
    }
    cin >> shark.y >> shark.x;
    shark.y--;
    shark.x--;

    while (S--) {
        // 물고기 이동
        grid_copy = grid;

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                for (int d = 0; d < 8; d++) {
                    if (!grid_copy[y][x][d]) continue;

                    int rotate_cnt = 8;
                    int can_go = 0;
                    int fish_cnt = grid_copy[y][x][d];
                    int ny, nx, nd = d;

                    while (rotate_cnt--) {
                        ny = y + diry[nd];
                        nx = x + dirx[nd];

                        // 해당 방향의 물고기 없으면 회전
                        if (ny < 0 || nx < 0 || ny >= 4 || nx >= 4) {
                            nd = (nd + 7) % 8;
                            continue;
                        }
                        // 상어 있거나 냄새 남아있으면 회전
                        if ((ny == shark.y && nx == shark.x) || smell[ny][nx]) {
                            nd = (nd + 7) % 8;
                            continue;
                        }
                        can_go = 1;
                        break;
                    }

                    if (!can_go) continue;
                    grid[y][x][d] -= fish_cnt;
                    grid[ny][nx][nd] += fish_cnt;
                }
            }
        }

        // 냄새 감소
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                if (smell[y][x] > 0) smell[y][x]--;
            }
        }

        // 상어 이동
        MAX = -1;
        for (int i = 0; i < 4; i++) {
            fill(visited[i].begin(), visited[i].end(), 0);
        }
        dfs(shark.y, shark.x, 0, 0);
        int ny = shark.y, nx = shark.x;
        for (int i = 0; i < 3; i++) {
            ny += dirr[dir_shark[i]];
            nx += dirc[dir_shark[i]];

            for (int d = 0; d < 8; d++) {
                if (grid[ny][nx][d]) smell[ny][nx] = 2; // 물고기 있었으면 냄새 남기기
                grid[ny][nx][d] = 0;
            }
        }
        shark = {ny, nx}; // 이동한 위치로 옮겨주기

        // 복제 마법
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                for (int d = 0; d < 8; d++) {
                    grid[y][x][d] += grid_copy[y][x][d];
                }
            }
        }
    }

    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 4; x++) {
            for (int d = 0; d < 8; d++) {
                ans += grid[y][x][d];
            }
        }
    }

