// 양방향 간선
// ai 가 1인곳은 못감 도착점 제외
// 0 --> N - 1 까지 최단 거리

#include <iostream>
#include <vector>
#include <queue>
using namespace std;
using ll = long long;
const ll INF = 1e16;

struct node {
    int to;
    ll time;
    bool operator<(node other) const {
        return time > other.time;
    }
};

ll dijkstra(int N, const vector<vector<node>>& edges, const vector<int>& ward) {
    priority_queue<node> pq;
    vector<ll> dist(N, INF);
    pq.push({0, 0});
    dist[0] = 0;

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.time > dist[now.to]) continue;

        for (const auto& edge : edges[now.to]) {
            ll next_time = now.time + edge.time;
            if (next_time >= dist[edge.to]) continue;
            // if (ward[edge.to] && edge.to != N - 1) continue; // 시야에 있으면 pass
            dist[edge.to] = next_time;
            pq.push({edge.to, next_time});
        }
    }

    return (dist[N - 1] == INF) ? -1 : dist[N - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    cin >> N >> M;
    vector<vector<node>> edges(N);
    vector<int> ward;
    for (int i = 0; i < N; i++) {
        int n;
        cin >> n;
        ward.push_back(n);
    }
    for (int i = 0; i < M; i++) {
        int from, to;
        ll time;
        cin >> from >> to >> time;
        // 시야에 보이면 간선 push 안함
        if (ward[from] || ward[to]) {
            if (from != N - 1 && to != N - 1) continue;
        }
        edges[from].push_back({to, time});
        edges[to].push_back({from, time});
    }

    cout << dijkstra(N, edges, ward) << "\n";
}

// 하루 지날때마다 bfs 하기
// bfs 하고 막힌 X 지점들
// 중간에 백조없이 물만 있는 지점들도 생각해서 얼음 녹이기
// 백조가 탐색한 공간은 저장해서 재탐색 안하기
// 백조 bfs --> 얼음 녹이기 순서로
// 백조 2개 다 탐색하면서 1 2 로 나눠서 visited하다가 서로 만날 때 조건 걸고 break
// 녹일 얼음 미리 구해놓고 녹인 다음에 다음 녹일 얼음 다시 넣어줌
// ---------------------------------------------------------------------------------------------------
// set 쓰지 말고 오늘 다음날 큐 각각 만들어서 4개 큐로 관리
// set은 시간복잡도 높은거 생각

#include <iostream>
#include <vector>
#include <queue>
#include <set>
#include <string>
using namespace std;
using PR = pair<int, int>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int R, C;
    vector<string> grid;
    cin >> R >> C;
    for (int r = 0; r < R; r++) {
        string line;
        cin >> line;
        grid.push_back(line);
    }

    vector<vector<int>> visited(R, vector<int>(C, 0)); // 백조가 방문한 곳 저장
    set<PR> ices_next;                                 // 다음날 녹을 빙판
    set<PR> swan1_next;                                // swan1 다음 지점
    set<PR> swan2_next;                                // swan2 다음 지점
    vector<PR> dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int swan_flag = 0;
    int ans = 0; // 며칠


    // 초기 조건 세팅
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) {
            if (grid[r][c] == 'L') {
                if (!swan_flag) {
                    swan1_next.insert({r, c});
                    swan_flag = 1;
                }
                else {
                    swan2_next.insert({r, c});
                }
            }
            else if (grid[r][c] == 'X') {
                for (const auto& dir : dirs) {
                    int ny = r + dir.second;
                    int nx = c + dir.first;
                    if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                    // 물, 백조에 인접하면 ices에 추가
                    if (grid[ny][nx] == '.' || grid[ny][nx] == 'L') {
                        ices_next.insert({r, c});
                        break;
                    }
                }
            }
        }
    }


    while (1) {
        queue<PR> q;
        set<PR> temp; // 복사용 임시 set

        // swan 1 탐색
        temp = swan1_next;
        swan1_next.clear();
        for (const auto& swan : temp) {
            if (visited[swan.first][swan.second] == 1) continue; // 이미 꺼내서 탐색했으면 pass
            q.push({swan.first, swan.second});
            visited[swan.first][swan.second] = 1;

            while (!q.empty()) {
                PR now = q.front();
                q.pop();

                for (const auto& dir : dirs) {
                    int ny = now.first + dir.first;
                    int nx = now.second + dir.second;

                    if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                    if (visited[ny][nx] == 1) continue;
                    if (grid[ny][nx] == 'X') {
                        swan1_next.insert({ny, nx});
                        continue;
                    }

                    visited[ny][nx] = 1;
                    q.push({ny, nx});
                }
            }
        }

        // swan 2 탐색
        temp = swan2_next;
        swan2_next.clear();
        for (const auto& swan : temp) {
            // swan 1 이 방문한 곳이면 정답 출력
            if (visited[swan.first][swan.second] == 1) {
                cout << ans << "\n";
                return 0;
            }
            if (visited[swan.first][swan.second] == 2) continue; // 이미 꺼내서 탐색했으면 pass
            q.push({swan.first, swan.second});
            visited[swan.first][swan.second] = 2;

            while (!q.empty()) {
                PR now = q.front();
                q.pop();

                for (const auto& dir : dirs) {
                    int ny = now.first + dir.first;
                    int nx = now.second + dir.second;

                    if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                    if (visited[ny][nx] == 2) continue;
                    if (grid[ny][nx] == 'X') {
                        swan2_next.insert({ny, nx});
                        continue;
                    }

                    visited[ny][nx] = 2;
                    q.push({ny, nx});
                }
            }
        }

        // ice 녹이기
        temp = ices_next;
        ices_next.clear();
        for (const auto& ice : temp) {
            grid[ice.first][ice.second] = '.';
        }
        for (const auto& ice : temp) {
            for (const auto& dir : dirs) {
                int ny = ice.first + dir.first;
                int nx = ice.second + dir.second;

                if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                if (grid[ny][nx] == 'X') ices_next.insert({ny, nx});
            }
        }

        ans++;
    }
}

// 1-based, NxN
// 다음칸에 머리 --> 사과 있으면 사과 없어지고 꼬리 그대로
//              --> 사과 없으면 꼬리칸 비워짐
// 벽이나 자기자신에 부딪히면 끝
// 처음 오른쪽 향한채로 (1,1) 시작
// 시작과 끝만 판단하면서 gird에 몸이 어디에 위치해있는지 표시
// grid에 dir 저장해서 tail 위치 갱신정보 알기 --> head 이동할때마다 이전 위치에 방향 저장
// ------------------------------------------------------------------------------------------
// 방향 설정할 때 음수로 -1이 아니라 +3으로 만들어주기
// 사과 먹고 그 자리의 사과 제거하는 로직 보충
// @@ deque를 사용하면 front에 머리 좌표 추가하고 back에서 꼬리 제거하기 편함

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct coord {
    int y, x;
};
int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};

int main() {
    int N, K, L;                       // 보드 크기, 사과의 개수, 방향 변환 횟수
    vector<vector<int>> board;         // 보드
    queue<pair<int, char>> dir_change; // 방향 변환 정보
    cin >> N >> K;
    board.resize(N + 1, vector<int>(N + 1, 0)); // 1-based의 NxN 그리드로 만들어줌
    for (int i = 0; i < K; i++) {
        int R, C; // 행 열
        cin >> R >> C;
        board[R][C] = 1;
    }
    cin >> L;
    for (int i = 0; i < L; i++) {
        int X;
        char C;
        cin >> X >> C;
        dir_change.push({X, C});
    }

    // 게임 시작
    vector<vector<int>> grid(N + 1, vector<int>(N + 1, -1)); // 몸의 위치 및 방향 정보 표시
    int TIME = 0;                                            // 게임 시간
    int DIR = 0;                                             // 현재 방향 (오른쪽 시작)
    coord head = {1, 1};
    coord tail = {1, 1};
    pair<int, char> next_dir = dir_change.front();
    dir_change.pop();

    while (1) {
        // 시간마다 방향 변환 확인
        if (TIME == next_dir.first) {
            if (next_dir.second == 'D') {
                DIR = (DIR + 1) % 4;
            }
            else {
                DIR = (DIR + 3) % 4;
            }
            // 다음 방향 변환 정보 갱신
            if (!dir_change.empty()) {
                next_dir = dir_change.front();
                dir_change.pop();
            }
        }
        TIME++;

        grid[head.y][head.x] = DIR; // 이전 위치에 방향 저장해 다음 위치 정보 남김
        int ny = head.y + diry[DIR];
        int nx = head.x + dirx[DIR];
        if (ny < 1 || nx < 1 || ny > N || nx > N) break; // 보드 벗어나면 종료
        if (grid[ny][nx] > -1) break;                    // 자기 자신과 부딪히면 종료

        head = {ny, nx};
        if (board[ny][nx] == 0) {
            int ndir = grid[tail.y][tail.x]; // 현재 tail의 dir 저장
            grid[tail.y][tail.x] = -1;       // 사과 없으면 tail 위치 비우기
            tail.y += diry[ndir];
            tail.x += dirx[ndir];
        }
        else {
            board[ny][nx] = 0;
        }
    }

    cout << TIME << "\n";
}

// N x M 그리드
// 0 이동가능  1 벽
// 벽은 1개까지만 제거 가능 최단거리 구하기
// visited를 3차원으로 벽 부순 횟수까지 추가해서 관리
// dist가 더 크면 push X

#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <algorithm>
using namespace std;
const int INF = 21e8;

struct node {
    int y, x, cnt, dist; // 좌표, 부순 횟수, 거리
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    cin >> N >> M;
    vector<vector<int>> grid(N, vector<int>(M));
    vector<vector<vector<int>>> dist(N, vector<vector<int>>(M, vector<int>(2, INF))); // N x M x 2
    for (int r = 0; r < N; r++) {
        string line;
        cin >> line;
        for (int c = 0; c < M; c++) {
            grid[r][c] = line[c] - '0';
        }
    }

    int diry[] = {0, 1, 0, -1};
    int dirx[] = {1, 0, -1, 0};
    queue<node> q;
    q.push({0, 0, 0, 1});
    dist[0][0][0] = 1;

    while (!q.empty()) {
        node now = q.front();
        q.pop();
        // cout << "(" << now.y << ", " << now.x << ") -> dist = " << now.dist << ", cnt = " << now.cnt << "\n";
        if (now.dist > dist[now.y][now.x][now.cnt]) continue; // 더 최단거리로 갱신됐으면 pass


        for (int i = 0; i < 4; i++) {
            int ny = now.y + diry[i];
            int nx = now.x + dirx[i];
            int ncnt = now.cnt;
            int ndist = now.dist + 1;


            if (ny < 0 || nx < 0 || ny >= N || nx >= M) continue; // grid 범위 체크
            // 다음 위치가 벽일 때
            if (grid[ny][nx]) {
                if (ncnt)
                    continue; // 부순횟수 1
                else
                    ncnt++; // 부순횟수 0
            }
            if (ndist >= dist[ny][nx][ncnt]) continue;
            dist[ny][nx][ncnt] = ndist;
            q.push({ny, nx, ncnt, ndist});
        }
    }

    int ans = min(dist[N - 1][M - 1][0], dist[N - 1][M - 1][1]);
    if (ans == INF) ans = -1;
    cout << ans << "\n";
}

// 0인 부분들을 플러드필 하면서 크기가 몇인지 구하기
// 플러드필 하면서 인접한 1인 grid의 좌표들을 저장해서 크기만큼 더해주기?
// 0 빈곳  |  1 벽  |  2 bfs 끝난곳
// ====================================================================================================
// 플러드필 하면서 다 set에 넣으면 오버헤드 커짐
// 미리 0인 부분들을 그룹화 해놓고 1일때 인접 그룹들을 더해서 하면 최적화 가능

#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <set>
using namespace std;
using pr = pair<int, int>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    vector<vector<int>> grid; // 맵
    vector<vector<int>> cnt;  // 이동할 수 있는 칸 개수
    int dirr[] = {0, 1, 0, -1};
    int dirc[] = {1, 0, -1, 0};

    cin >> N >> M;
    grid.resize(N, vector<int>(M));
    cnt.resize(N, vector<int>(M, 0));
    for (int r = 0; r < N; r++) {
        string s;
        cin >> s;
        for (int c = 0; c < M; c++) {
            grid[r][c] = s[c] - '0';
        }
    }

    for (int r = 0; r < N; r++) {
        for (int c = 0; c < M; c++) {
            if (grid[r][c] == 1) {
                cnt[r][c]++;
            }
            else if (grid[r][c] == 0) {
                set<pr> COORD; // 인접한 1의 좌표들
                int size = 0;  // 0 플러드필의 크기

                queue<pr> q;
                grid[r][c] = 2;
                q.push({r, c});

                while (!q.empty()) {
                    pr now = q.front();
                    q.pop();
                    size++;

                    for (int i = 0; i < 4; i++) {
                        int nr = now.first + dirr[i];
                        int nc = now.second + dirc[i];
                        if (nr < 0 || nc < 0 || nr >= N || nc >= M) continue;

                        if (grid[nr][nc] == 1) {
                            COORD.insert({nr, nc});
                        }
                        else if (grid[nr][nc] == 0) {
                            grid[nr][nc] = 2;
                            q.push({nr, nc});
                        }
                    }
                }

                for (const auto& coord : COORD) {
                    cnt[coord.first][coord.second] += size;
                }
            }
        }
    }

    for (int r = 0; r < N; r++) {
        for (int c = 0; c < M; c++) {
            cout << cnt[r][c] % 10;
        }
        cout << "\n";
    }
}

