int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, S;
    vector<int> presum;
    int left = 0, right = 1;
    int MIN = 1e8;

    cin >> N >> S;
    presum.resize(N + 1, 0); // 1-based index
    for (int i = 1; i <= N; i++) {
        int n;
        cin >> n;
        presum[i] = presum[i - 1] + n;
    }

    // right가 수열의 길이를 넘거나 MIN이 1일 때 (left == right)
    while (right <= N && left != right) {
        int cursum = presum[right] - presum[left]; // 부분합
        // cout << "left = " << left << ", right = " << right << ", sum = " << cursum << " --> MIN = " << MIN << "\n";

        if (cursum < S) {
            right++;
            continue;
        }
        else {
            MIN = min(MIN, right - left);
            left++;
        }
    }
    if (!left) MIN = 0;

    cout << MIN << "\n";
}

// 큐 2개로 관리
// 플러드필 하면서 지훈이 큐가 비게 되면 impossible
// 지훈 --> fire 순서
// 미로의 외곽에 도착하면 탈출시간 출력
// ========================================================================
// size만큼 queue 돌려주기 --> 같은 시간대 다 돌려줘야됨

#include <iostream>
#include <vector>
#include <queue>
#include <string>
using namespace std;

struct node {
    int y, x, time = 0; // 좌표, 탈출시간
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int R, C;            // R x C
    vector<string> miro; // 미로
    node J;              // 지훈이 초기위치
    vector<node> F;      // 불 초기위치
    int diry[] = {0, 1, 0, -1};
    int dirx[] = {1, 0, -1, 0};

    cin >> R >> C;
    miro.resize(R);
    for (int r = 0; r < R; r++) {
        cin >> miro[r];
        for (int c = 0; c < C; c++) {
            if (miro[r][c] == 'J')
                J = {r, c};
            else if (miro[r][c] == 'F')
                F.push_back({r, c});
        }
    }

    queue<node> jihun;
    queue<node> fire;
    jihun.push(J);
    for (const auto& f : F) {
        fire.push(f);
    }

    while (!jihun.empty()) {
        // 불 시작
        int size = fire.size();
        while (size--) {
            node now = fire.front();
            fire.pop();

            for (int i = 0; i < 4; i++) {
                int ny = now.y + diry[i];
                int nx = now.x + dirx[i];

                if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                if (miro[ny][nx] == '#' || miro[ny][nx] == 'J' || miro[ny][nx] == 'F') continue;

                miro[ny][nx] = 'F';
                fire.push({ny, nx});
            }
        }

        size = jihun.size();
        while (size--) {
            node now = jihun.front();
            jihun.pop();
            // 외곽에 위치하면 종료
            if (now.y == 0 || now.x == 0 || now.y == R - 1 || now.x == C - 1) {
                cout << now.time + 1 << "\n";
                return 0;
            }

            for (int i = 0; i < 4; i++) {
                int ny = now.y + diry[i];
                int nx = now.x + dirx[i];

                if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue;
                if (miro[ny][nx] == '#' || miro[ny][nx] == 'J' || miro[ny][nx] == 'F') continue;

                miro[ny][nx] = 'J';
                jihun.push({ny, nx, now.time + 1});
            }
        }
    }

    cout << "IMPOSSIBLE\n";
}

// 먼저 녹이고 bfs하면서 2덩어리 이상인지 확인

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

struct node {
    int y, x;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    vector<vector<int>> grid;
    vector<vector<int>> temp;
    int cnt = 0; // 빙판 남은 개수
    int ans = 0; // 몇년

    cin >> N >> M;
    grid.resize(N, vector<int>(M, 0));
    temp.resize(N, vector<int>(M, 0));
    for (int y = 0; y < N; y++) {
        for (int x = 0; x < M; x++) {
            cin >> grid[y][x];
            if (grid[y][x]) cnt++;
        }
    }

    int diry[] = {0, 1, 0, -1};
    int dirx[] = {1, 0, -1, 0};

    while (1) {
        // 빙판 개수가 0개 될 때까지 한 덩어리였으면 0 출력하고 종료
        if (cnt == 0) {
            cout << 0 << "\n";
            break;
        }

        ans++;
        // 녹이기
        temp = grid;
        for (int y = 0; y < N; y++) {
            for (int x = 0; x < M; x++) {
                if (!grid[y][x]) continue; // 0 이면 pass
                int zero = 0;              // 0과 접한 지점의 수

                for (int i = 0; i < 4; i++) {
                    int ny = y + diry[i];
                    int nx = x + dirx[i];

                    if (ny < 0 || nx < 0 || ny >= N || nx >= M) continue; // grid 벗어나면 pass
                    if (grid[ny][nx]) continue;                           // 0 아니면 pass
                    zero++;
                }

                temp[y][x] -= zero;
                if (temp[y][x] <= 0) {
                    cnt--;
                    temp[y][x] = 0;
                }
            }
        }
        grid = temp;
        // cout << "\n";
        // for (int y = 0; y < N; y++) {
        //     for (int x = 0; x < M; x++) {
        //         cout << grid[y][x] << " ";
        //     }
        //     cout << "\n";
        // }

        // 플러드필
        queue<node> q;
        int seperated_flag = 0; // 분리 됐는지 flag

        for (int y = 0; y < N; y++) {
            for (int x = 0; x < M; x++) {
                if (!temp[y][x]) continue; // 0 이면 pass
                q.push({y, x});

                // flag가 1이면 2 덩어리로 분리되었으니 출력하고 종료
                if (seperated_flag) {
                    cout << ans << "\n";
                    return 0;
                }

                while (!q.empty()) {
                    node now = q.front();
                    q.pop();

                    for (int i = 0; i < 4; i++) {
                        int ny = now.y + diry[i];
                        int nx = now.x + dirx[i];

                        if (ny < 0 || nx < 0 || ny >= N || nx >= M) continue; // grid 벗어나면 pass
                        if (!temp[ny][nx]) continue;                          // 0 아니면 pass

                        temp[ny][nx] = 0;
                        q.push({ny, nx});
                    }
                }
                seperated_flag = 1;
            }
        }
    }
}

