// N개의 수열
// i ~ j 의 합이 M이 되는 경우의 수
// 왼쪽부터 시작해서 작으면 right++, 크면 left++
// 누적합 이용해서 부분합 만들기

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int N, M;
    cin >> N >> M;
    vector<int> presum(N + 1, 0); // 누적합
    for (int i = 1; i < N + 1; i++) {
        int num;
        cin >> num;
        presum[i] = presum[i - 1] + num;
    }

    int ans = 0;
    int left = 0;
    int right = 1;
    while (1) {
        int sum = presum[right] - presum[left];
        if (sum == M) {
            ans++;
            right++;
            if (right == N + 1) break;
        }
        else if (sum < M) {
            right++;
            if (right == N + 1) break; // 범위 안벗어나게
        }
        else if (sum > M) {
            left++;
        }
    }

    cout << ans << "\n";
}

#include <iostream>
using namespace std;

int main() {
    int N, L;
    cin >> N >> L;

    while (L <= 100) {
        // 수열의 합 공식: N = L*x + L*(L-1)/2
        // x = (N - L*(L-1)/2) / L
        long long sum = (long long)L * (L - 1) / 2;

        if ((N - sum) % L == 0) { // 나누어떨어지는지 확인
            long long start = (N - sum) / L;

            if (start >= 0) { // 음수가 아닌 경우
                for (int i = 0; i < L; i++) {
                    cout << start + i << " ";
                }
                return 0;
            }
        }
        L++;
    }

    cout << -1;
    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, K;
    int visited[210000] = {0};
    cin >> N >> K;


    queue<int> q;
    q.push(N);
    visited[N] = 1;

    while (!q.empty()) {
        int now = q.front();
        q.pop();
        if (now == K) break;

        for (int i = 0; i < 3; i++) {
            int next = 1;
            switch (i) {
            case 0:
                next = now * 2;
                break;
            case 1:
                next = now + 1;
                break;
            case 2:
                next = now - 1;
                break;
            }

            if (next < 0 || next >= 210000) continue;
            if (visited[next] > 0) continue;
            visited[next] = visited[now] + 1;
            q.push(next);
        }
    }

    cout << visited[K] - 1;
}

#include <iostream>
#include <queue>
using namespace std;

// 1초 후에 -1 or +1
// 0초 후에 *2
// N --> K 가장 빠른 시간

struct node {
    int pos, time; // 위치, 시간
    bool operator<(node right) const {
        return time > right.time;
    }
};
int N, K;      // 수빈, 동생
int T[100001]; // 시간

void dijkstra(int start) {
    for (int i = 0; i <= 100000; i++) {
        T[i] = 21e8;
    }
    T[start] = 0;
    priority_queue<node> pq;
    pq.push({start, 0});

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.time > T[now.pos]) continue; // T 값보다 크면 pass

        // 순간이동
        int npos = now.pos * 2;
        if (npos >= 0 && npos <= 100000 && now.time < T[npos]) {
            T[npos] = now.time;
            pq.push({npos, now.time});
        }
        // X-1 이동
        npos = now.pos - 1;
        if (npos >= 0 && npos <= 100000 && now.time + 1 < T[npos]) {
            T[npos] = now.time + 1;
            pq.push({npos, now.time + 1});
        }
        // X+1 이동
        npos = now.pos + 1;
        if (npos >= 0 && npos <= 100000 && now.time + 1 < T[npos]) {
            T[npos] = now.time + 1;
            pq.push({npos, now.time + 1});
        }
    }
}

int main() {
    cin >> N >> K;

    dijkstra(N);

    cout << T[K];
}

// 시작점부터 플러드필 하면서 저장
// 0: 갈 수 없는 땅  |  1: 갈 수 있는 땅  |  2: 목표지점
// 갈 수 없는 땅 0 유지
// 갈 수 있는 땅은 grid 바꿔가며 갱신 1인데 갱신 안됐으면 -1로 바꿔서 출력

