            if (grid[y][x] == 1)
                grid[y][x] = -1;
            else if (grid[y][x] == 2)
                target = {y, x};
        }
    }

    // 플러드필 시작
    queue<coord> q;
    q.push(target);
    grid[target.y][target.x] = 0;

