// 지금까지 만난 알파벳 중복 X
// 최대로 지나갈 수 있는 칸 수 구하기
// 왔던길로 어차피 중복해서 못가기 때문에 visited 필요 X
// 지금까지 만난 알파벳만 저장
// 백트래킹으로
// ----------------------------------------------------------------------------------------
// set 쓰면서 dfs bfs 하면 터질 확률 높음 --> 그냥 배열로 확인

#include <iostream>
#include <vector>
#include <unordered_set>
#include <string>
#include <algorithm>
using namespace std;

int R, C;
vector<string> grid;
int alphas[26];
int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};
int ans = 1;

void dfs(int y, int x, int cnt) {
    for (int i = 0; i < 4; i++) {
        int ny = y + diry[i];
        int nx = x + dirx[i];

        if (ny < 0 || nx < 0 || ny >= R || nx >= C) continue; // grid 체크
        if (alphas[grid[ny][nx] - 'A']) continue;             // 알파벳 중복 체크

        alphas[grid[ny][nx] - 'A'] = 1;
        dfs(ny, nx, cnt + 1);
        alphas[grid[ny][nx] - 'A'] = 0;
    }
    ans = max(ans, cnt);
    return;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> R >> C;
    for (int i = 0; i < R; i++) {
        string line;
        cin >> line;
        grid.push_back(line);
    }

    alphas[grid[0][0] - 'A'] = 1;
    dfs(0, 0, 1);

    cout << ans << "\n";
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> edges(N);
    vector<int> visited(N, 0);

    for (int i = 0; i < M; i++) {
        int from, to;
        cin >> from >> to;
        edges[from - 1].push_back(to - 1);
        edges[to - 1].push_back(from - 1);
    }

    int ans = 0;
    queue<int> q;

    for (int i = 0; i < N; i++) {
        if (visited[i]) continue;
        q.push(i);

        while (!q.empty()) {
            int now = q.front();
            q.pop();
            visited[now] = 1;

            for (const auto& n : edges[now]) {
                if (visited[n]) continue;
                visited[n] = 1;
                q.push(n);
            }
        }
        ans++;
    }

    cout << ans << "\n";
}

// 모든 경우의 수 조합해서 돌려보기
// permutation 사용해보기

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

struct coord {
    int y, x;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M;
    vector<vector<int>> grid;     // N x M
    vector<vector<int>> grid_cpy; // grid 복사본
    vector<coord> Empty;          // 벽 세울 후보 좌표
    vector<coord> virus;          // 바이러스 좌표
    vector<int> choose;           // 어떤 좌표 선택할지 permutation용
    int safe = 0;
    int ans = -1;
    int diry[] = {0, 1, 0, -1};
    int dirx[] = {1, 0, -1, 0};

    cin >> N >> M;
    grid.resize(N, vector<int>(M));
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < M; c++) {
            cin >> grid[r][c];

            if (grid[r][c] == 0) {
                Empty.push_back({r, c});
                safe++;
            }
            else if (grid[r][c] == 2) {
                virus.push_back({r, c});
                safe++;
            }
        }
    }
    choose.assign(Empty.size(), 0);
    for (int i = 0; i < 3; i++) {
        choose[i] = 1;
        safe--;
    }

    // 모든 경우의 수 bfs
    do {
        int safe_cpy = safe; // ans 비교용
        grid_cpy = grid;
        for (int i = 0; i < choose.size(); i++) {
            if (!choose[i]) continue;
            grid_cpy[Empty[i].y][Empty[i].x] = 1;
        }
        queue<coord> q;
        for (const auto& v : virus) {
            q.push({v.y, v.x});
        }

        while (!q.empty()) {
            coord now = q.front();
            q.pop();
            safe_cpy--;

            for (int i = 0; i < 4; i++) {
                int ny = now.y + diry[i];
                int nx = now.x + dirx[i];

                if (ny < 0 || nx < 0 || ny >= N || nx >= M) continue;
                if (grid_cpy[ny][nx]) continue;
                grid_cpy[ny][nx] = 2;
                q.push({ny, nx});
            }
        }

        ans = max(ans, safe_cpy);
    } while (prev_permutation(choose.begin(), choose.end()));

    cout << ans << "\n";
}

// '.' 빈 공간 -> 52  |  '*' 벽 -> -1  |  '$' 문서 -> 100
// 대문자: 문 -> 26 ~ 51   |  소문자: 문을 열 수 있는 열쇠 -> 0 ~ 25
// queue에 넣어주면서 열쇠 있는지 확인
// 열쇠가 있다면 바로 큐에 넣고 없으면 좌표 기록해놓고 대기
// ==========================================================================================
// 벡터 초기화 신경써주기 --> 자주 초기화 해줘야되면 assign으로
// 테두리 신경써야되면 바깥에 1줄 패딩 해주는것도 좋음

#include <iostream>
#include <vector>
#include <string>
#include <string.h>
#include <queue>
#include <algorithm>
using namespace std;

struct coord {
    int y, x;
};

int h, w;                    // 높이, 너비
vector<vector<int>> grid;    // 맵
vector<int> key;             // 가진 열쇠
vector<vector<coord>> door;  // 문 좌표
vector<vector<int>> visited; // 방문 여부
int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};
int ans = 0;

void init() {
    grid.clear();
    key.assign(26, 0);
    door.assign(26, vector<coord>());
    visited.clear();
    ans = 0;
}

void input() {
    cin >> h >> w;
    grid.resize(h, vector<int>(w));
    visited.resize(h, vector<int>(w, 0));
    for (int y = 0; y < h; y++) {
        string row;
        cin >> row;
        for (int x = 0; x < w; x++) {
            if (row[x] >= 'A' && row[x] <= 'Z') {
                grid[y][x] = row[x] - 'A' + 26;
            }
            else if (row[x] >= 'a' && row[x] <= 'z') {
                grid[y][x] = row[x] - 'a';
            }
            else if (row[x] == '*') {
                grid[y][x] = -1;
            }
            else if (row[x] == '.') {
                grid[y][x] = 52;
            }
            else if (row[x] == '$') {
                grid[y][x] = 100;
            }
        }
    }

    string keys;
    cin >> keys;
    if (keys[0] == '0') return;
    for (const auto& k : keys) {
        key[k - 'a'] = 1;
    }
}

void solution() {
    queue<coord> q;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            if (!(y == 0 || x == 0 || y == h - 1 || x == w - 1)) continue;
            if (grid[y][x] == -1)
                continue; // 벽이거나 방문했으면 pass
            else if (grid[y][x] >= 26 && grid[y][x] < 52) {
                if (!key[grid[y][x] - 26]) {
                    door[grid[y][x] - 26].push_back({y, x});
                    visited[y][x] = 1;
                    continue;
                }
            }
            else if (grid[y][x] >= 0 && grid[y][x] < 26) {
                if (!key[grid[y][x]]) {
                    for (const auto& d : door[grid[y][x]]) {
                        q.push({d.y, d.x});
                    }
                }
                key[grid[y][x]] = 1;
            }

            visited[y][x] = 1;
            q.push({y, x});
        }
    }

    while (!q.empty()) {
        coord now = q.front();
        q.pop();
        if (grid[now.y][now.x] == 100) ans++;

        for (int i = 0; i < 4; i++) {
            int ny = now.y + diry[i];
            int nx = now.x + dirx[i];

            if (ny < 0 || nx < 0 || ny >= h || nx >= w) continue;
            if (grid[ny][nx] == -1) continue;
            if (visited[ny][nx]) continue;

            if (grid[ny][nx] >= 26 && grid[ny][nx] < 52) {
                if (!key[grid[ny][nx] - 26]) {
                    door[grid[ny][nx] - 26].push_back({ny, nx});
                    visited[ny][nx] = 1;
                    continue;
                }
            }
            else if (grid[ny][nx] >= 0 && grid[ny][nx] < 26) {
                if (!key[grid[ny][nx]]) {
                    for (const auto& d : door[grid[ny][nx]]) {
                        q.push({d.y, d.x});
                    }
                }
                key[grid[ny][nx]] = 1;
            }

            visited[ny][nx] = 1;
            q.push({ny, nx});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T;
    cin >> T;
    while (T--) {
        init();
        input();
        solution();
        cout << ans << "\n";
    }
}

