            int size = 0;
            Node* now = Head;
            while (now) {
                size++;
                now = now->next;
            }
            cout << size << "\n";
        }
        else if (com == "empty") {
            if (Head == nullptr) {
                cout << 1 << "\n";
            }
            else {
                cout << 0 << "\n";
            }
        }
        else if (com == "front") {
            if (Head == nullptr) {
                cout << -1 << "\n";
            }
            else {
