    int N, M;
    cin >> N >> M;

    vector<vector<node>> edges(N + 1);
    while (M--) {
        int from, to, cost;
        cin >> from >> to >> cost;
        edges[from].push_back({to, cost});
        edges[to].push_back({from, cost});
    }

    cout << dijkstra(N, edges) << "\n";
}

