// 루트는 항상 1
// 루트에서 가장 거리가 먼 지점 먼저 구하고 한번 더 거리가 먼 지점을 구하면 --> 지름

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct edge {
    int node, weight;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    vector<vector<edge>> edges;
    vector<int> visited;
    vector<int> dist;

    cin >> N;
    edges.resize(N + 1);
    visited.resize(N + 1, 0);
    dist.resize(N + 1, 0);
    for (int i = 0; i < N - 1; i++) {
        int A, B, W;
        cin >> A >> B >> W;
        edges[A].push_back({B, W});
        edges[B].push_back({A, W});
    }

    int target = -1; // 루트에서 가장 먼 노드
    int MAX = 0;
    queue<int> q;
    q.push(1);
    visited[1] = 1;

    while (!q.empty()) {
        int now = q.front();
        q.pop();
        target = (MAX > dist[now]) ? target : now;
        MAX = max(MAX, dist[now]);

        for (const auto& edge : edges[now]) {
            if (visited[edge.node]) continue;
            visited[edge.node] = 1;
            dist[edge.node] = dist[now] + edge.weight;
            q.push(edge.node);
        }
    }

    // 한번 더
    dist.assign(N + 1, 0);
    visited.assign(N + 1, 0);
    q.push(target);
    visited[target] = 1;
    MAX = 0;

    while (!q.empty()) {
        int now = q.front();
        q.pop();
        MAX = max(MAX, dist[now]);

        for (const auto& edge : edges[now]) {
            if (visited[edge.node]) continue;
            visited[edge.node] = 1;
            dist[edge.node] = dist[now] + edge.weight;
            q.push(edge.node);
        }
    }

    cout << MAX << "\n";
}

// 1번 --> N번 최단 거리
// 임의의 2개 정점을 반드시 통과
// 이동했던 곳 또 이동 가능
// 정점 사이에 간선은 하나만
// 0-based로 풀기
// v1 --> v2 --> N / v2 --> v1 --> N 2가지 경우 비교

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

struct node {
    int num, length;
    bool operator<(node right) const {
        return length > right.length;
    }
};
int N, E;                  // 정점의 개수, 간선의 개수
vector<vector<node>> path; // a --> b 간선 정보
int v1, v2;
int dist[810];

int dijkstra(int start, int end, int temp_dist) {
    for (int i = 0; i < N; i++) {
        dist[i] = 21e8;
    }
    dist[start] = temp_dist;
    priority_queue<node> pq;
    pq.push({start, temp_dist});

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.length > dist[now.num]) continue; // 다익스트라 조건
        if (now.length > dist[end]) break;        // 목적지 길이보다 크면 종료

        for (int i = 0; i < path[now.num].size(); i++) {
            node next = path[now.num][i];
            int next_dist = now.length + next.length;

            if (next_dist >= dist[next.num]) continue;
            dist[next.num] = next_dist;
            pq.push({next.num, next_dist});
        }
    }

    if (dist[end] != 21e8) {
        return dist[end];
    }
    else {
        return -1;
    }
}

int main() {
    cin >> N >> E;
    path.resize(N);
    for (int i = 0; i < E; i++) {
        int a, b, c; // a번 정점부터 b번 정점까지 거리 c의 길
        cin >> a >> b >> c;
        path[a - 1].push_back({b - 1, c});
        path[b - 1].push_back({a - 1, c});
    }
    cin >> v1 >> v2;


    int len1 = dijkstra(0, v1 - 1, 0);
    if (len1 != -1) {
        len1 = dijkstra(v1 - 1, v2 - 1, len1);
        if (len1 != -1) {
            len1 = dijkstra(v2 - 1, N - 1, len1);
        }
    }
    int len2 = dijkstra(0, v2 - 1, 0);
    if (len2 != -1) {
        len2 = dijkstra(v2 - 1, v1 - 1, len2);
        if (len2 != -1) {
            len2 = dijkstra(v1 - 1, N - 1, len2);
        }
    }

    int ans = -1;
    if (len1 != -1 && len2 != -1) {
        ans = min(len1, len2);
    }
    else if (len1 == -1) {
        ans = len2;
    }
    else if (len2 == -1) {
        ans = len1;
    }

    cout << ans;
}

#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;


int dp[501][501]; // left ~ right 까지 dp
int sum[501];     // 누적합 저장
int k;

void init() {
    memset(dp, 0, sizeof(dp));
    memset(sum, 0, sizeof(sum));
}
void input() {
    cin >> k;
}
void solution() {
    vector<int> file(k + 1);

    for (int i = 1; i <= k; i++) {
        cin >> file[i];
        sum[i] = sum[i - 1] + file[i];
    }

    // 2부터 k까지 길이 늘려가면서 dp 시작
    for (int len = 2; len <= k; len++) {
        // 시작점 설정
        for (int start = 1; start <= k - len + 1; start++) {
            int end = start + len - 1;
            dp[start][end] = 21e8; // 초기값 최대로 설정
            // start, end 사이 구간 설정
            for (int mid = start; mid < end; mid++) {
                int cost = dp[start][mid] + dp[mid + 1][end] + sum[end] - sum[start - 1];
                dp[start][end] = min(dp[start][end], cost);
            }
        }
    }
}
int main() {
    int T;
    cin >> T;
    for (int tc = 1; tc <= T; tc++) {
        init();
        input();
        solution();
        cout << dp[1][k] << "\n";
    }
    return 0;
}

// N개 마을, M개 단방향 도로
// 목표 마을로 갔다가 돌아오기
// 1-based

#include <iostream>
#include <vector>
#include <queue>
#include <string.h>
#include <algorithm>
using namespace std;

struct node {
    int to, time;
    bool operator<(node other) const {
        return time > other.time; // 오름차순으로 정렬
    }
};

int dist[1001]; // 다익스트라용 걸린 시간

// 시작점, 끝점, 걸린 시간, 간선, 답
void dijkstra(int start, int end, int time, vector<vector<node>> edge, int& ans) {
    for (int i = 1; i <= edge.size() - 1; i++) {
        dist[i] = 21e8;
    }
    priority_queue<node> pq;
    pq.push({start, time});
    dist[start] = time;

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (now.time > dist[now.to]) continue;

        for (int i = 0; i < edge[now.to].size(); i++) {
            node next = edge[now.to][i];
            int next_time = now.time + next.time;
            if (next_time >= dist[next.to]) continue;
            dist[next.to] = next_time;
            pq.push({next.to, next_time});
        }
    }

    ans = max(ans, dist[end]);
}

int main() {
    int N, M, X; // 마을 수, 도로 수, 목표 마을
    int ans = -1;
    cin >> N >> M >> X;
    vector<vector<node>> edge(N + 1); // N개 마을의 간선들
    for (int i = 0; i < M; i++) {
        int from, to, time;
        cin >> from >> to >> time;
        edge[from].push_back({to, time}); // 양방향 X
    }

    for (int start = 1; start <= N; start++) {
        dijkstra(start, X, 0, edge, ans);
        dijkstra(X, start, dist[X], edge, ans);
    }

    cout << ans << "\n";
}

