// 단방향 간선
// 간선이 유일하지 않은 경우도 있음
// 각 최단경로마다 지나온 도시 개수, 경로 출력
// ------------------------------------------------------------------------------------------------
// 플로이드워셜은 다익스트라랑 다르게 parent 설정
// 2차원 -1 로 초기화 하고 경유하는 k의 parent를 따라가게 갱신

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
const int INF = 1e8;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> table(n, vector<int>(n, INF));
    vector<vector<int>> parent(n, vector<int>(n, -1));

    for (int i = 0; i < n; i++) {
        table[i][i] = 0;
    }
    for (int i = 0; i < m; i++) {
        int from, to;
        int cost;
        cin >> from >> to >> cost;
        if (cost < table[from - 1][to - 1]) {
            table[from - 1][to - 1] = cost;
            parent[from - 1][to - 1] = from - 1;
        }
    }

    // 플로이드 워셜
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cmp = table[i][k] + table[k][j];
                if (cmp < table[i][j]) {
                    table[i][j] = cmp;
                    parent[i][j] = parent[k][j]; // 경유하는 k --> j 지점 가져옴
                }
            }
        }
    }

    // table 출력
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int output = (table[i][j] == INF) ? 0 : table[i][j];
            cout << output << " ";
        }
        cout << "\n";
    }

    // 경로 출력
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (table[i][j] == INF || i == j) {
                cout << 0 << "\n";
            }
            else {
                vector<int> path;
                for (int now = j; now != -1; now = parent[i][now]) {
                    path.push_back(now);
                }

                reverse(path.begin(), path.end());
                cout << path.size() << " ";
                for (const auto& p : path) {
                    cout << p + 1 << " ";
                }
                cout << "\n";
            }
        }
    }
}

// dfs 하면서 컴포넌트 묶기
// 컴포넌트 수가 답
// 싸이클 이루면 그대로 cnt 끼어드는 경우는 cnt--
// ========================================================================================
// 최악의 경우 스택 오버플로우 발생
// union-find 로 푸는것이 정석
// dfs 로직 개선
/*
void dfs(int y, int x) {
    state[y][x] = 1;  // 방문중

    int d = grid[y][x];
    int ny = y + diry[d];
    int nx = x + dirx[d];

    if (state[ny][nx] == 0) {
        dfs(ny, nx);
    }
    else if (state[ny][nx] == 1) {
        // 방문중인 노드를 다시 만남 -> 사이클 1개 발견
        cnt++;
    }

    state[y][x] = 2;  // 방문끝
}
*/

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int N, M;
vector<vector<int>> grid;    // 방향
vector<vector<int>> visited; // 컴포넌트 종류  | -1: 방문 X, 0: 방문중, 1~: 컴포넌트 종류
int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};
int cnt = 0;

int dfs(int y, int x) {
    if (visited[y][x] == 0) {
        return cnt;
    }
    else if (visited[y][x] > 0) {
        cnt--;
        return visited[y][x];
    }

    visited[y][x] = 0;
    int d = grid[y][x];
    int ny = y + diry[d];
    int nx = x + dirx[d];
    return visited[y][x] = dfs(ny, nx);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> M;
    grid.resize(N, vector<int>(M, 0));
    visited.resize(N, vector<int>(M, -1));
    for (int y = 0; y < N; y++) {
        string s;
        cin >> s;
        for (int x = 0; x < M; x++) {
            if (s[x] == 'R')
                grid[y][x] = 0;
            else if (s[x] == 'D')
                grid[y][x] = 1;
            else if (s[x] == 'L')
                grid[y][x] = 2;
            else if (s[x] == 'U')
                grid[y][x] = 3;
        }
    }

    for (int y = 0; y < N; y++) {
        for (int x = 0; x < M; x++) {
            if (visited[y][x] != -1) continue;
            cnt++;
            dfs(y, x);
        }
    }

    cout << cnt << "\n";
}

