// N개의 회의에 대해 사용시간 배정
// 시작 ~ 끝
// 겹치지않게 최대한 많이
// 끝나는 시간 내림차순 + 길이 짧은거 -> 우선순위큐로 정렬
// ----------------------------------------------------------------
// 끝나는 시간 오름차순 정렬 -> 그 다음 시간 짧은 순대로

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct info {
    int start, end;
    bool operator<(info other) const {
        if (end != other.end) {
            return end > other.end;
        }
        else {
            return start > other.start; // (1,3) (3,3) 이 경우 (1,3)이 먼저 와야 만족하므로 오름차순
        }
    }
};

int main() {
    int N;
    priority_queue<info> conf;
    cin >> N;
    for (int i = 0; i < N; i++) {
        int start, end;
        cin >> start >> end;
        conf.push({start, end});
    }

    int ans = 1;
    int last = conf.top().end;
    conf.pop();

    while (!conf.empty()) {
        info now = conf.top();
        conf.pop();

        if (now.start < last) continue; // 마지막 끝 지점보다 먼저 pass
        last = now.end;                 // 마지막 시작 지점 갱신
        ans++;
    }

    cout << ans << "\n";
}

// 건물 짓는 순서 주어짐
// 건설시간 필요
// 부모 건물이 다 완성되어야 건설 가능
// 건설 동시 진행 가능
// 최소 건설 시간 출력
// 1번부터 시작해서 pq에 넣고 제일 작은 시간만큼 감소
// flag++ 로 건설 가능 여부 판단해 가능하면 pq에 삽입
// -----------------------------------------------------------------------------
// 위상정렬 문제 + dp

#include <iostream>
#include <vector>
#include <deque>
#include <algorithm>
#include <string.h>
using namespace std;

struct node {
    int num, time; // 건물 번호, 건설 시간
    bool operator<(node right) const {
        return time < right.time;
    }
};
int N, K;                // 건물의 개수 N, 건설 순서 개수 K
vector<int> D;           // 건설시간
vector<vector<int>> seq; // 건설 순서
int W;                   // 건설해야할 번호 W
int flag[1010];          // 건설 가능 여부 확인용
int flag_cmp[1010];      // flag 비교용


void init() {
    D.clear();
    seq.clear();
    memset(flag, 0, sizeof(flag));
    memset(flag_cmp, 0, sizeof(flag_cmp));
}

void input() {
    cin >> N >> K;
    D.resize(N);
    seq.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> D[i];
    }
    for (int i = 0; i < K; i++) {
        int from, to;
        cin >> from >> to;
        seq[from - 1].push_back(to - 1);
        flag[to - 1]++;
    }
    cin >> W;
}

int solution() {
    deque<node> pq;    // pq 대신 sort하면서 사용
    vector<int> start; // 진입차수가 0인 시작지점 모음
    int cnt = 0;       // 총 건설시간
    for (int i = 0; i < N; i++) {
        if (flag[i] == 0) {
            start.push_back(i);
        }
    }
    for (int n : start) {
        pq.push_back({n, D[n]});
    }

    // cout << "\n";

    while (!pq.empty()) {
        node MIN = pq.front();
        pq.pop_front();
        cnt += MIN.time;
        // 건물 W의 건설 조건이 모두 충족되면 ans에 더하고 종료
        if (MIN.num == W - 1) return cnt;
        // cout << cnt << "\n";
        // 최소 건설시간 만큼 큐에 있는 다른 시간들 감소
        if (!pq.empty()) {
            for (node& target : pq) {
                target.time -= MIN.time;
            }
        }

        // 건설 마치면 연결된 다음 건물들 건설 가능한지 확인
        for (int next : seq[MIN.num]) {
            flag_cmp[next]++;
            if (flag_cmp[next] == flag[next]) pq.push_back({next, D[next]});
        }

        // pq 오름차순으로 정렬
        sort(pq.begin(), pq.end());
        // for (node target : pq) {
        //     cout << target.num << " " << target.time << " | ";
        // }
        // cout << "\n";
    }
}

int main() {
    int T;
    cin >> T;
    for (int tc = 1; tc <= T; tc++) {
        init();
        input();
        int ans = solution();
        cout << ans << "\n";
    }
}

