int main() {
    int M, N, m, n;
    vector<vector<int>> grid;

    cin >> M >> N >> m >> n;
    grid.assign(M, vector<int>(N, 0));
    for (int y = 0; y < M; y++) {
        for (int x = 0; x < N; x++) {
