            seq.push_back(n);
            int good = 1; // 좋은 수열 아닌지 판단

            for (int len = 1; len <= idx / 2 && good; len++) {
                good = 0;
                for (int i = 0; i < len && !good; i++) {
                    if (seq[seq.size() - 1 - i] == seq[seq.size() - 1 - len - i])
                        good = 0;
                    else {
                        good = 1;
