// 단방향 그래프
// 모든 장소 한번씩 방문하고 돌아오기
// 이동할수 없는 길은 0
// 비트마스킹 dp 2차원
// 일단 백트래킹으로

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;
const int INF = 21e8;

int N; // 최대 13
vector<vector<int>> Cost;
vector<vector<int>> dp;
int sum = 0;

void dfs(int last, int visited) {
    if (visited == (1 << N) - 1) {
        return;
    }

    for (int i = 1; i < N; i++) {
        if (visited & (1 << i) || !Cost[last][i]) continue;
        int nextVisited = visited | (1 << i);
        if (dp[last][visited] + Cost[last][i] >= dp[i][nextVisited]) continue;
        dp[i][nextVisited] = dp[last][visited] + Cost[last][i];
        dfs(i, nextVisited);
    }
}

int main() {
    cin >> N;
    Cost.assign(N, vector<int>(N, 0));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int cost;
            cin >> cost;
            Cost[i][j] = cost;
        }
    }
    dp.assign(N, vector<int>(1 << N, INF));
    dp[0][1] = 0;
    dfs(0, 1 << 0);

    int ans = INF;
    for (int i = 1; i < N; i++) {
        if (!Cost[i][0]) continue;
        int minCost = dp[i][(1 << N) - 1] + Cost[i][0];
        ans = min(ans, minCost);
    }

    cout << ans;
}

/*
n까지의 정수를 조합
각 index에 대해 나누어떨어져야함
n <= 15
백트래킹 하면서 세기?
2 6
*/

class Solution {
    int cnt = 0;

    void dfs(int idx, int used, int n) {
        if (idx == n) {
            cnt++;
            return;
        }

        for (int i = 0; i < n; i++) {
            if (used & (1 << i)) continue;
            if ((idx + 1) % (i + 1) != 0 && (i + 1) % (idx + 1) != 0) continue;

            dfs(idx + 1, used | (1 << i), n);
        }
    }

public:
    int countArrangement(int n) {
        dfs(0, 0, n);
        return cnt;
    }
};

