#include <vector>
#include <string>
#include <unordered_set>
#include <algorithm>
using namespace std;

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int len = s.length();
        unordered_set<char> visited;

        int left = 0, right = 0;
        int MAX = 0;

        while (left < len && right < len) {
            if (visited.find(s[right]) != visited.end()) {
                MAX = max(MAX, right - left);

                while (visited.find(s[right]) != visited.end()) {
                    visited.erase(s[left]);
                    left++;
                }
            }
            else {
                visited.insert(s[right]);
                right++;
            }
        }
        /* 개선
        for (int right = 0; right < len; right++) {
            while (visited.find(s[right]) != visited.end()) {
                visited.erase(s[left]);
                left++;
            }

            visited.insert(s[right]);
            MAX = max(MAX, right - left + 1);
        }
        */
        MAX = max(MAX, right - left);

        return MAX;
    }
};

/*
dp 느낌
job length <= 5 * 10e4
Time <= 10e9
profit <= 10e4
end time 정렬하고 start time 정렬
구간별로 end Time 기준으로 dp
시간초과남
====================================================================================
작업 종료 시간을 정렬하고 순서대로 dp하면 모든 시간에 대해 계산할 필요 X
dp[i] = i번째 작업까지 진행했을 때 최대 이득
*/

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
    struct job {
        int start, end, profit;
    };
    static bool cmp(job a, job b) {
        if (a.end != b.end) return a.end < b.end;
        return a.start < b.start;
    }

    vector<job> jobs;
    vector<int> dp;
    vector<int> ends;

public:
    int jobScheduling(vector<int>& startTime, vector<int>& endTime, vector<int>& profit) {
        int size = startTime.size();
        jobs.resize(size);
        dp.resize(size + 1, 0);
        ends.resize(size);

        for (int i = 0; i < size; i++) {
            jobs[i] = {startTime[i], endTime[i], profit[i]};
            ends[i] = endTime[i];
        }
        sort(jobs.begin(), jobs.end(), cmp);
        sort(ends.begin(), ends.end());

        for (int i = 0; i < size; i++) {
            int nprofit;

            auto it = upper_bound(ends.begin(), ends.begin() + i, jobs[i].start);

            if (it == ends.end()) {
                nprofit = jobs[i].profit;
            }
            else {
                int idx = it - ends.begin();
                nprofit = dp[idx] + jobs[i].profit;
            }

            dp[i + 1] = max(dp[i], nprofit);
        }

        return dp[size];
    }
};

