/*
N <= 1000,  -1e6 <= 좌표 <= 1e6
점 사이의 거리 -> 맨해튼 거리
모든 점을 연결하는 최소 비용
MST?
모든 노드 조합에 대해 거리 구하고 진행
*/

#include <vector>
#include <queue>
#include <cmath>
#include <algorithm>
using namespace std;
using ll = long long;
using pr = pair<int, int>;

struct node {
    int to;
    ll dist;
    bool operator<(const node other) const {
        return dist > other.dist;
    }
};

class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int len = points.size();
        vector<vector<pr>> edges(len);
        for (int i = 0; i < len - 1; i++) {
            for (int j = i + 1; j < len; j++) {
                ll dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]);
                edges[i].push_back({j, dist});
                edges[j].push_back({i, dist});
            }
        }

        priority_queue<node> pq;
        vector<int> visited(len, 0);
        ll MIN = 0;
        pq.push({0, 0});

        while (!pq.empty()) {
            node now = pq.top();
            pq.pop();
            if (visited[now.to]) continue;

            visited[now.to] = 1;
            MIN += now.dist;

            for (const auto& next : edges[now.to]) {
                auto [to, dist] = next;
                if (visited[to]) continue;
                pq.push({to, dist});
            }
        }

        return MIN;
    }
};

/*
n <= 14
작업 시간들이 주어지고 세션타임 한번 안에 작업 시간의 합만큼 할 수 있음
최소 세션타임 구하기
그리디?
정렬해서 하면 반례 생김  [7 4 3 8 10], 12
안되면 다음거 찾기
======================================================================
그리디로 하면 시간초과
비트마스킹 dp로 바꿔서 풀기
dp(used, {session, empty})
*/

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
    struct task {
        int cnt, emptyTime;
    };
    vector<task> dp;

    void func(vector<int>& tasks, int sessionTime, int visited) {
        for (int i = 0; i < tasks.size(); i++) {
            if (visited & (1 << i)) continue;

            task now = dp[visited];
            int newSession = 0, ncnt = now.cnt, nemptyTime;
            if (now.emptyTime < tasks[i]) newSession = 1;
            if (newSession) {
                ncnt++;
                nemptyTime = sessionTime - tasks[i];
            }
            else {
                nemptyTime = now.emptyTime - tasks[i];
            }

            int nvisited = visited | (1 << i);
            if (ncnt > dp[nvisited].cnt) continue;
            if (ncnt == dp[nvisited].cnt && nemptyTime <= dp[nvisited].emptyTime) continue;

            dp[nvisited] = {ncnt, nemptyTime};
            func(tasks, sessionTime, nvisited);
        }
    }

public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        dp.assign(1 << tasks.size(), {15, sessionTime});
        dp[0] = {1, sessionTime};
        func(tasks, sessionTime, 0);
        return dp[(1 << tasks.size()) - 1].cnt;
    }
};

/*
N <= 1e5, num <= 1e4, target <= 1e9
합이 target을 넘는 최소길이
현재 sum 확인
-> target 이상이면 MIN 기록하고 left++, 이하면 right++;
*/

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int len = nums.size();
        int left = 0, right = 0, sum = 0;
        int MIN = 1e8;

        while (right < len) {
            sum += nums[right++];

            while (sum >= target) {
                MIN = min(MIN, right - left);
                sum -= nums[left++];
            }
        }

        MIN = (MIN == 1e8) ? 0 : MIN;
        return MIN;
    }
};

/*
n <= 1e5, dist <= 1e5
방향성 그래프
필수경로 다익스트라 src1 src2 둘 다 거쳐서 dest에 도착
다익스트라 2번해서 비교하기
필수경로 포함했는지 dest에서 확인 -> parent? flag?
아니면 dist를 2차원으로 관리해서 0: 필수경로 안지남, 1: 필수경로 지남으로 관리
====================================================================================
무조건 한 지점에서 출발해서 경유하는 문제가 아님
각각 출발해서 합쳐지는것도 가능
다익스트라에 src1 src2 같이 넣고 관리?
비트마스킹으로 관리하면서 해보기
====================================================================================
각각 다익스트라 해놓고 '역방향 그래프'를 이용해 dest로부터 모든 정점에 대해 다익스트라
이후 합류지점을 정해서 계산하기
*/

#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
    using ll = long long;
    const ll INF = 1e12;
    struct edge {
        int to;
        ll dist;
    };
    struct node {
        int to;
        ll dist;
        bool operator<(const node& other) const {
            return dist > other.dist;
        }
    };

    vector<vector<edge>> Edge;
    vector<vector<edge>> ReverseEdge;
    vector<vector<ll>> dist;

    void dijkstra(int start, int idx) {
        priority_queue<node> pq;
        dist[start][idx] = 0;
        pq.push({start, 0});

        while (!pq.empty()) {
            node now = pq.top();
            pq.pop();
            if (now.dist > dist[now.to][idx]) continue;

            if (idx <= 1) {
                for (const auto& next : Edge[now.to]) {
                    ll ndist = now.dist + next.dist;
                    if (ndist >= dist[next.to][idx]) continue;
                    dist[next.to][idx] = ndist;
                    pq.push({next.to, ndist});
                }
            }
            else {
                for (const auto& next : ReverseEdge[now.to]) {
                    ll ndist = now.dist + next.dist;
                    if (ndist >= dist[next.to][idx]) continue;
                    dist[next.to][idx] = ndist;
                    pq.push({next.to, ndist});
                }
            }
        }
    }

public:
    long long minimumWeight(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
        Edge.resize(n);
        ReverseEdge.resize(n);
        dist.assign(n, vector<ll>(3, INF));
        for (auto& e : edges) {
            Edge[e[0]].push_back({e[1], e[2]});
            ReverseEdge[e[1]].push_back({e[0], e[2]});
        }

        dijkstra(src1, 0);
        dijkstra(src2, 1);
        dijkstra(dest, 2);

        ll MIN = INF;
        for (int i = 0; i < n; i++) {
            if (dist[i][0] == INF || dist[i][1] == INF || dist[i][2] == INF) continue;

            ll cmp = 0;
            for (const auto& d : dist[i]) {
                cmp += d;
            }
            MIN = min(MIN, cmp);
        }


        MIN = (MIN == INF) ? -1 : MIN;
        return MIN;
    }
};

/*
n <= 14   |   num <= 1e7
XOR 연산 값을 최소로 만드는 배열 조정
비트마스킹 dp 느낌
순차dp로 검사하면서 가보기
nums1은 순서대로 nums2만 선택하면서 가기
dp[mask] = mask 비트 고른거에서 최소값
*/

#include <vector>
using namespace std;

class Solution {
public:
    int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
        int size = nums1.size();
        const int INF = 21e8;
        vector<int> dp(1 << size, INF);
        dp[0] = 0;

        for (int visited = 0; visited < (1 << size); visited++) {
            int cnt = __builtin_popcount(visited);

            for (int i = 0; i < size; i++) {
                if (visited & (1 << i)) continue;

                int nvisited = visited | (1 << i);
                dp[nvisited] = min(dp[nvisited], dp[visited] + (nums1[cnt] ^ nums2[i]));
            }
        }

        return dp[(1 << size) - 1];
    }
};

/*
n <= 200
0 -> n-1 까지 최단거리의 개수
mod 10e9 + 7
그냥 parent 배열 여러개 저장해서 다익스트라 해놓고 계산하기 -> 계산할 때 dp 안하면 타임리밋
다익스트라 진행하면서 바로 계산해서 갱신하는걸로
*/

#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
    using ll = long long;
    const ll INF = 1e16;
    const int MOD = 1e9 + 7;
    struct edge {
        int to;
        ll dist;
        bool operator<(const edge other) const {
            return dist > other.dist;
        }
    };
    struct node {
        ll dist;
        int cnt;
    };

    vector<vector<edge>> edges;
    vector<node> nodes;

    void dijkstra() {
        priority_queue<edge> pq;
        nodes[0] = {0, 1};
        pq.push({0, 0});

        while (!pq.empty()) {
            edge now = pq.top();
            pq.pop();
            if (now.dist > nodes[now.to].dist) continue;

            for (const auto& next : edges[now.to]) {
                ll ndist = now.dist + next.dist;
                if (ndist >= nodes[next.to].dist) {
                    if (ndist == nodes[next.to].dist) {
                        nodes[next.to].cnt += nodes[now.to].cnt;
                        nodes[next.to].cnt %= MOD;
                    }
                    continue;
                }

                nodes[next.to] = {ndist, nodes[now.to].cnt};
                pq.push({next.to, ndist});
            }
        }
    }

public:
    int countPaths(int n, vector<vector<int>>& roads) {
        edges.resize(n);
        nodes.assign(n, {INF, 0});
        for (const auto& road : roads) {
            edges[road[0]].push_back({road[1], road[2]});
            edges[road[1]].push_back({road[0], road[2]});
        }

        dijkstra();
        return nodes[n - 1].cnt;
    }
};

/*
n <= 15, 방향성 있는 그래프
한 학기에 k개 까지만 선택 가능 -> 최소 학기 구하기
비트마스킹 DP + 재귀
permutation으로 조합 생성
*/

#include <vector>
#include <queue>
#include <deque>
#include <algorithm>
using namespace std;

class Solution {
    const int INF = 1e8;

    vector<vector<int>> edges;
    vector<int> Initindegree;
    vector<int> dp;
    deque<int> Initseq;

    void func(vector<vector<int>>& edges, int k, int visited, deque<int> seq, vector<int> indegree) {
        int size = seq.size();
        if (size == 0) return;

        int nvisited = visited;
        vector<int> nindegree = indegree;
        deque<int> nseq = seq;

        if (size > k) {
            vector<int> order(size, 0);
            for (int i = 0; i < k; i++) {
                order[i] = 1;
            }

            do {
                nvisited = visited;
                nindegree = indegree;
                nseq.clear();

                for (int i = 0; i < size; i++) {
                    int now = seq[i];

                    if (!order[i]) {
                        nseq.push_back(now);
                        continue;
                    }

                    nvisited |= 1 << now;

                    for (int& next : edges[now]) {
                        if (!--nindegree[next]) nseq.push_back(next);
                    }
                }

                if (dp[nvisited] <= dp[visited] + 1) continue;
                dp[nvisited] = dp[visited] + 1;
                func(edges, k, nvisited, nseq, nindegree);

            } while (prev_permutation(order.begin(), order.end()));
        }

        else {
            while (size--) {
                int now = nseq.front();
                nseq.pop_front();
                nvisited |= 1 << now;

                for (int& next : edges[now]) {
                    if (!--nindegree[next]) nseq.push_back(next);
                }
            }

            if (dp[nvisited] <= dp[visited] + 1) return;
            dp[nvisited] = dp[visited] + 1;
            func(edges, k, nvisited, nseq, nindegree);
        }
    }

public:
    int minNumberOfSemesters(int n, vector<vector<int>>& relations, int k) {
        edges.resize(n);
        Initindegree.resize(n, 0);
        dp.resize(1 << n, INF);
        dp[0] = 0;

        for (const auto& r : relations) {
            edges[r[0] - 1].push_back(r[1] - 1);
            Initindegree[r[1] - 1]++;
        }
        for (int i = 0; i < n; i++) {
            if (!Initindegree[i]) Initseq.push_back(i);
        }

        func(edges, k, 0, Initseq, Initindegree);

        return dp[(1 << n) - 1];
    }
};

