/*
위상정렬 dp
n <= 5e4  |  time <= 1e4
==================================================================
우선순위큐 안쓰고 따로 finish(n) 만들어서 max값 저장해놓아도 가능
dag 최장경로
*/

#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
    struct node {
        int to, time;
        bool operator<(const node& other) const {
            return time > other.time;
        }
    };


public:
    int minimumTime(int n, vector<vector<int>>& relations, vector<int>& time) {
        vector<vector<int>> edge(n);
        vector<int> indegree(n, 0);
        for (const auto& r : relations) {
            edge[r[0] - 1].push_back(r[1] - 1);
            indegree[r[1] - 1]++;
        }

        priority_queue<node> pq;
        for (int i = 0; i < n; i++) {
            if (indegree[i]) continue;
            pq.push({i, time[i]});
        }

        int ans = 0;
        while (!pq.empty()) {
            node now = pq.top();
            pq.pop();
            ans = now.time;

            for (const auto& next : edge[now.to]) {
                indegree[next]--;
                if (!indegree[next]) pq.push({next, now.time + time[next]});
            }
        }

        return ans;
    }
};

/*
k개의 부분수열로 나눴을 때 수열들의 합을 동일하게 만들 수 있는지
1 <= k <= n <= 16,  nums[i] <= 1e4
연속하진 않아도 됨
비트마스킹?
재귀로 구해보기
어떻게 k개의 부분집합으로 쪼갤지 생각 -> 쉽지않음
===============================================================
dfs로 비트마스킹 하면서 sum 관리하면됨
메모이제이션도 필요 중복 조합이 많음
*/

#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
    float avg;
    vector<int> result;

    bool func(vector<int>& nums, int k, int cnt, int mask, int sum) {
        if (cnt == k) return true;

        for (int i = 0; i < nums.size(); i++) {
            if (mask & (1 << i)) continue;

            int nsum = sum + nums[i];
            int nmask = mask | (1 << i);
            if (result[nmask]) continue;

            if (nsum > avg) {
                continue;
            }
            else if (nsum == avg) {
                if (func(nums, k, cnt + 1, nmask, 0)) return true;
            }
            else {
                if (func(nums, k, cnt, nmask, nsum)) return true;
            }
        }

        result[mask] = 1;
        return false;
    }

public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total % k != 0) return false;

        avg = total / k;
        result.assign(1 << nums.size(), 0);

        return func(nums, k, 0, 0, 0);
    }
};

/*
n <= 1e4,  edges <= 2e4
다익스트라?
확률이 클수록 좋음
*/

#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
    using db = double;

    struct edge {
        int to;
        db dist;
    };
    struct node {
        int to;
        db dist;
        bool operator<(const node& other) const {
            return dist < other.dist;
        }
    };

public:
    double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb,
                          int start_node, int end_node) {
        vector<vector<edge>> Edge(n);
        int size = edges.size();
        for (int i = 0; i < size; i++) {
            Edge[edges[i][0]].push_back({edges[i][1], succProb[i]});
            Edge[edges[i][1]].push_back({edges[i][0], succProb[i]});
        }

        vector<db> dist(n, 0);
        priority_queue<node> pq;
        dist[start_node] = 1;
        pq.push({start_node, 1});

        while (!pq.empty()) {
            node now = pq.top();
            pq.pop();
            if (now.dist < dist[now.to]) continue;

            for (const auto& next : Edge[now.to]) {
                db ndist = now.dist * next.dist;
                if (ndist <= dist[next.to]) continue;

                dist[next.to] = ndist;
                pq.push({next.to, ndist});
            }
        }

        return dist[end_node];
    }
};

/*
N <= 1e5, -1e4 <= num <= 1e4
연속된 k개 nums 중 MAX
매번 k개 방문하면 최대 1e10
================================================
단조 덱
i를 윈도우의 끝 인덱스로 사용하면서 진행
front()가 가장 큰 원소의 idx
새로 원소 추가할때마다 기존 front 지우고 deque에 있는 원소보다 작을때까지 pop_back
*/

#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        int len = nums.size();
        vector<int> ans;
        deque<int> dq;

        for (int i = 0; i < len; i++) {
            if (!dq.empty() && dq.front() < i - k + 1) dq.pop_front();

            while (!dq.empty() && nums[dq.back()] <= nums[i]) {
                dq.pop_back();
            }

            dq.push_back(i);
            if (i < k - 1) continue;
            ans.push_back(nums[dq.front()]);
        }

        return ans;
    }
};

/*
n <= 3e4
위상정렬인데 그룹에 묶여있음
그룹의 차수 확인 필요
선행 작업이 같은 그룹에 있는지 다른 그룹에 있는지 고려해야됨
같은 그룹 넣을 때 다 확인하면 중복되니 한번만 할 수 있게
===============================================================
위상정렬을 2번 사용해야함
그룹 우선수위 -> 작업 우선순위
그룹의 순서가 정렬되면 다른 그룹의 작업 순서도 보장
*/

#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> sortItems(int n, int m, vector<int>& group, vector<vector<int>>& beforeItems) {
        vector<int> groupId = group;
        int groupcnt = m;
        for (int i = 0; i < n; i++) {
            if (group[i] != -1) continue;
            groupId[i] = groupcnt++;
        }

        vector<vector<int>> taskEdges(n);
        vector<int> taskIndegree(n, 0);
        vector<vector<int>> groupEdges(groupcnt);
        vector<int> groupinDegree(groupcnt, 0);
        vector<int> grouporder;
        vector<vector<int>> sortedTask(groupcnt);

        for (int i = 0; i < n; i++) {
            for (int prev : beforeItems[i]) {
                if (groupId[prev] == groupId[i]) {
                    taskEdges[prev].push_back(i);
                    taskIndegree[i]++;
                }
                else {
                    groupEdges[groupId[prev]].push_back(groupId[i]);
                    groupinDegree[groupId[i]]++;
                }
            }
        }

        queue<int> q;

        // group 위상정렬
        for (int i = 0; i < groupcnt; i++) {
            if (groupinDegree[i]) continue;
            q.push(i);
        }

        while (!q.empty()) {
            int now = q.front();
            q.pop();
            grouporder.push_back(now);

            for (const int& next : groupEdges[now]) {
                groupinDegree[next]--;
                if (groupinDegree[next]) continue;
                q.push(next);
            }
        }
        if (grouporder.size() != groupcnt) return {};

        // task 위상정렬
        int taskcnt = 0;
        for (int i = 0; i < n; i++) {
            if (taskIndegree[i]) continue;
            q.push(i);
        }

        while (!q.empty()) {
            int now = q.front();
            q.pop();
            sortedTask[groupId[now]].push_back(now);
            taskcnt++;

            for (const int& next : taskEdges[now]) {
                taskIndegree[next]--;
                if (taskIndegree[next]) continue;
                q.push(next);
            }
        }
        if (taskcnt != n) return {};

        vector<int> ans = {};
        for (auto& order : grouporder) {
            for (const auto& task : sortedTask[order]) {
                ans.push_back(task);
            }
        }

        return ans;
    }
};

/*
N <= 1000, 1 <= K <= 50
k개로 나눠서 나눈 배열의 합의 최대가 최소가 되도록
배열에서 연속된 서브배열로 나눈다 -> 누적합?
N - 1 개 중에서 K - 1 개 선택
백트래킹? 하면서 MAX 값 넘으면 break 하면서 가지치기
================================================================================
백트래킹 하면 무조건 시간초과
파라메트릭 서치
*/

#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        int left = *max_element(nums.begin(), nums.end());
        int right = accumulate(nums.begin(), nums.end(), 0);
        int ans;

        while (left <= right) {
            int mid = (left + right) / 2;
            int sum = 0, cnt = 1;

            for (int& num : nums) {
                if (sum + num > mid) {
                    sum = 0;
                    cnt++;
                }
                sum += num;
            }

            if (cnt > k) {
                left = mid + 1;
            }
            else {
                ans = mid;
                right = mid - 1;
            }
        }

        return ans;
    }
};

/*
N <= 2e4, -1000 <= num <= 1000
합이 k인 연속된 부분배열의 수
누적합 구하면서 구할때마다 map에 뺏을때 k가 되는 값이 있는지 확인?
*/

#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        int size = nums.size();

        vector<int> presum(size + 1, 0);
        unordered_map<int, int> freq;
        freq[0]++;
        int cntSubarray = 0;

        for (int i = 0; i < size; i++) {
            presum[i + 1] = presum[i] + nums[i];
            int target = presum[i + 1] - k;
            if (freq.find(target) != freq.end()) cntSubarray += freq[target];
            freq[presum[i + 1]]++;
        }

        return cntSubarray;
    }
};

/*
N <= 1e5, -1e4 <= num <= 1e4
nums에서 k번째까지 많이 나오는 숫자 출력
sort
음수가 있어서 그냥 배열 말고 해시맵으로
