void find(int start, int& ans) {
    priority_queue<node> pq;
    pq.push({start, 0});

    while (!pq.empty()) {
        node now = pq.top();
        pq.pop();
        if (visited[now.to] == 1) continue;
        ans += now.cost;
        visited[now.to] = 1;

        for (int i = 0; i < island[now.to].size(); i++) {
            node next = island[now.to][i];
            if (visited[next.to] == 1) continue;
            pq.push(next);
        }
    }
}

