string solution(vector<string> participant, vector<string> completion) {
    string answer = "";
    unordered_map<string, int> map;
    for (string player : participant) {
        if (map.find(player) == map.end())
            map[player] = 1;
        else {
            int num = map[player];
            map[player] = num + 1;
        }
    }
    // for (auto m : map) {
    //     cout<<m.first<<" "<<m.second<<"\n";
    // }

    for (string c : completion) {
        int num = map[c];
        map[c] = num - 1;
    }
    for (auto m : map) {
        if (m.second == 0) continue;
        answer += m.first;
        break;
    }

    return answer;
}

// 이분탐색을 결정론적 관점으로 바꿔서 풀기 --> 파라매트릭 서치
// 최소 시간, 최대 시간을 해서 각 심사관별로 나누고 얼마만큼의 사람이 가능한지 구함
// 계속해서 lower_bound 찾아내기

#include <string>
#include <vector>
#include <algorithm>
using namespace std;

long long solution(int n, vector<int> times) {
    sort(times.begin(), times.end()); // 오름차순 정렬

    long long MIN = 1;
    long long MAX = (long long)times[times.size() - 1] * n; // 최대로 걸리는 시간

    while (MIN <= MAX) {
        long long mid = (MIN + MAX) / 2;
        long long cnt = 0;
        for (int time : times) {
            cnt += mid / time; // 시간 안에 각 심사관이 맡을 수 있는 사람 수
        }
        if (cnt >= n)
            MAX = mid - 1;
        else
            MIN = mid + 1;
    }

    return MIN;
}

// 모든 wire 한번씩 삭제하면서 계산
// 1 ~ n --> 0-based로 바꾸기

#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <cmath>
#include <string.h>
using namespace std;

void func(int index, int n, vector<vector<int>> wires, int& answer) {
    vector<vector<int>> node(n); // 양방향 연결
    int visited[n];              // 방문 여부
    int cnt1 = 0;
    int cnt2 = 0;
    int flag = 0;
    memset(visited, 0, sizeof(visited));

    // 노드 연결집합 만들어주기
    for (int i = 0; i < wires.size(); i++) {
        if (index == i) continue;
        int from = wires[i][0] - 1; // 0-based
        int to = wires[i][1] - 1;   // 0-based
        node[from].push_back(to);
        node[to].push_back(from);
    }

    for (int i = 0; i < n; i++) {
        if (visited[i] == 1) continue;
        queue<int> q; // bfs 큐
        q.push(i);
        visited[i] = 1;
        if (cnt1 > 0) flag = 1;

        while (!q.empty()) {
            int now = q.front();
            q.pop();
            if (flag == 0)
                cnt1++;
            else
                cnt2++;

            // 연결된 노드들 큐에 삽입
            for (int next : node[now]) {
                if (visited[next] == 1) continue;
                visited[next] = 1;
                q.push(next);
            }
        }
    }

    int dif = abs(cnt1 - cnt2); // 개수 차이 return
    if (dif < answer) answer = dif;
}

int solution(int n, vector<vector<int>> wires) {
    int answer = 21e8;

    for (int i = 0; i < wires.size(); i++) {
        func(i, n, wires, answer);
    }

    return answer;
}

