int solution(vector<vector<int>> sizes) {
    int MAX1 = 0, MAX2 = 0; // 가로 세로 길이 최대
    int ans;
    // int MIN = 21e8;    // 넓이 최소
    for (vector<int> wallet : sizes) {
        pair<int, int> temp1 = {MAX1, MAX2}; // 가로세로 1
        pair<int, int> temp2 = {MAX1, MAX2}; // 가로세로 2
        int size1, size2;                    // 2가지 경우 크기 비교
        // cout<<len1.first<<" "<<len1.second<<"\n";
        // 가로 X 세로
        if (wallet[0] > temp1.first) temp1.first = wallet[0];
        if (wallet[1] > temp1.second) temp1.second = wallet[1];
        size1 = temp1.first * temp1.second;
        // 세로 X 가로
        if (wallet[1] > temp2.first) temp2.first = wallet[1];
        if (wallet[0] > temp2.second) temp2.second = wallet[0];
        size2 = temp2.first * temp2.second;

        // 넓이가 더 작은 경우를 갱신
        if (size1 < size2) {
            MAX1 = temp1.first;
            MAX2 = temp1.second;
        }
        else {
            MAX1 = temp2.first;
            MAX2 = temp2.second;
        }
    }

    ans = MAX1 * MAX2;
    return ans;
}

// 백트래킹으로 풀기
// 2^20이라 time limit X
// 한번은 더하고 다음엔 빼기

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

// 재귀
void find(vector<int> numbers, int target, int& ans, int index, int sum) {
    if (index >= numbers.size()) {
        if (sum == target) ans++;
        return;
    }
    // 더하기
    find(numbers, target, ans, index + 1, sum + numbers[index]);
    // 빼기
    find(numbers, target, ans, index + 1, sum - numbers[index]);
}

int solution(vector<int> numbers, int target) {
    int ans = 0; // 방법 개수
    sort(numbers.begin(), numbers.end(), greater<>());

    find(numbers, target, ans, 0, 0);

    return ans;
}

// 테트리스, 흰칸 채워넣기 50X50크기
// 최대한 빈칸 얼마나 채울 수 있는지
// 회전 가능
// 조각 넣었을 때 빈칸이 있으면 안됨
// table에서 먼저 조각 정보 --> 그리드 0 1 정보를 그대로 떠서 저장
// 3차원으로 그리드 저장

#include <iostream>
#include <string>
#include <vector>
#include <queue>
using namespace std;

struct coord {
    int y, x;
};

int diry[] = {0, 1, 0, -1};
int dirx[] = {1, 0, -1, 0};
int visited[50][50]; // 방문 여부

// table의 조각들 저장
// 기존 table, 조각 시작 y, 조각 시작 x, 조각 저장할 3차원 벡터
void table_save(vector<vector<int>> table, int off_y, int off_x, vector<vector<vector<int>>>& pieces) {
    vector<vector<int>> temp(6, vector<int>(12)); // 임시 저장, 조각들 최대 길이 6 * 2
    vector<vector<int>> save;                     // 사이즈에 맞춘 저장할 그리드
    int size_y = 0, size_x = 0;                   // save 크기 resize
    queue<coord> q;
    q.push({0, 5}); // 0~5, 0~11 y x
    visited[off_y][off_x] = 1;

    while (!q.empty()) {
        coord now = q.front();
        q.pop();
        temp[now.y][now.x] = 1;

        // 4방향 탐색
        for (int i = 0; i < 4; i++) {
            int next_y = now.y + diry[i];
            int next_x = now.x + dirx[i];
            if (next_y < 0 || next_x < 0 || next_y >= table.size() || next_x >= table.size()) continue;
            if (table[next_y][next_x] == 0) continue;
            if (visited[next_y][next_x] == 1) continue;
            visited[next_y][next_x] = 1;
            temp[next_y][next_x] = 1;
            q.push({next_y, next_x});
        }
    }
}

int solution(vector<vector<int>> game_board, vector<vector<int>> table) {
    int answer = -1;
    vector<vector<vector<int>>> pieces; // 조각들 저장

    for (int y = 0; y < table.size(); y++) {
        for (int x = 0; x < table.size(); x++) {
            if (table[y][x] == 0) continue;
            table_save(table, y, x, pieces);
        }
    }

    return answer;
}
